export const RECEIVERSHIP_INTRO_HTML = "<p class=\"body\"><b>MANAGEMENT AGREEMENT</b></p>\n<p class=\"body\"><b>THIS AGREEMENT</b> (&#8220;Agreement&#8221;) is effective as of the Commencement Date, by and between <b>%%MANAGER_NAME%%</b>, a %%MANAGER_STATE%% (&#8220;Manager&#8221;) and <b>%%OWNER_NAME%%</b>, a %%OWNER_STATE%% limited liability company (the &#8220;Owner&#8221;). Owner acts by and through %%SPECIAL_SERVICER_NAME%%, in its capacity as Special Servicer (&#8220;Special Servicer&#8221;) to %%TRUSTEE_NAME%%, as Trustee for the registered holders of the %%CERTIFICATE_SERIES%% (&#8220;Sole Member&#8221;).</p>\n<p class=\"body\"><b>RECITALS:</b></p>\n<p class=\"ind\">A.\tOwner is the owner of certain real property and certain improvements contained thereon, having a street address of %%PROPERTY_ADDRESS_FULL%% and more commonly known as %%PROPERTY_ADDRESS_FULL%% (the &#8220;Property&#8221;), as described on Exhibit C attached hereto.</p>\n<p class=\"ind\">B.\tSole Member is a “real estate mortgage investment conduit” (a “<i><b>REMIC</b></i>”) within the meaning of Section 860A et. seq. of the Internal Revenue Code of 1986 (the “<i><b>Code</b></i>”) and as such Owner is subject to limitations relating to its ownership of the Property.</p>\n<p class=\"ind\">C.\tSpecial Servicer is empowered to act on behalf of Owner.</p>\n<p class=\"ind\">D.\tManager agrees to operate the Property pursuant to the terms of this Agreement.</p>\n<p class=\"body\"><b>NOW, THEREFORE</b>, in consideration of the mutual promises and covenants herein contained, Owner and Manager agree as follows:</p>\n";

export interface ReceivershipPageChunk { titleHtml: string; subtitleHtml: string; body: string; }

export const RECEIVERSHIP_PAGE_CHUNKS: ReceivershipPageChunk[] = [
  { titleHtml: "<h2 class=\"art\">ARTICLE 1</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFINITIONS</h3>", body: "<p class=\"body\"><b>1.01</b><b>\tDefinitions.</b></p>\n<p class=\"body\">As used herein the following terms shall have the respective meanings indicated below:</p>\n<p class=\"deflist\"><i><b>Affiliate</b></i> - any corporation or other entity controlled by, controlling or under common control with Owner or Manager, as applicable.  The words “<i><b>control</b></i>,” “<i><b>controlled</b></i>” and “<i><b>controlling</b></i>” mean ownership, directly or indirectly, of ten percent (10%) or more of the legal or beneficial ownership interest of such corporation or other entity or the power to direct or cause the direction of the management and policies of any such entity.</p>\n<p class=\"deflist\">[Intentionally Omitted].</p>\n<p class=\"deflist\"><i><b>Approved Budget</b></i> – as defined in Section 6.02(a).</p>\n<p class=\"deflist\"><i><b>Bank Account</b></i> – as defined in Section 6.03(b).</p>\n<p class=\"deflist\"><i><b>Building </b></i>- all buildings, structures and improvements now located or hereafter constructed on the Site and all fixtures and equipment attached to, forming a part of and necessary for the operation of such buildings, structures or improvements as a <b>[</b><b>___ multi-family___</b><b>]</b> property (including, without limitation, heating, lighting, plumbing, sanitary system, air-conditioning, refrigeration, kitchen, and similar items) and such (i) commercial space (ii) garage and parking spaces, (iii) storage and service areas, (iv) recreational facilities and areas, (v) public grounds, permanently affixed signage, (vi) other facilities and appurtenances  as presently exist on the Property or are hereafter added thereon during the Term, subject to the terms of this Agreement.</p>\n<p class=\"deflist\"><i><b>Capital Expenditures</b></i> – as defined in Section 5.05.</p>\n<p class=\"deflist\"><i><b>Capital Expenditures Budget</b></i> – as defined in Section 6.02(b).</p>\n<p class=\"deflist\"><i><b>Close-Out Fee</b></i> – as defined in Section 3.03.</p>\n<p class=\"deflist\"><i><b>Cash </b></i><i><b>Close Out</b></i><i><b> </b></i><i><b>Process </b></i>– as defined in Section 7.03.</p>\n<p class=\"deflist\">[Intentionally Omitted].</p>\n<p class=\"deflist\"><i><b>Centralized Services Expenses</b></i> – as defined in Paragraph G of Exhibit B attached.</p>\n<p class=\"deflist\"><i><b>Commencement Date</b></i> – as defined in Section 2.01.</p>\n<p class=\"deflist\"><i><b>Defaulting Party</b></i> – as defined in Section 11.02(a).</p>\n<p class=\"deflist\"><i><b>Disposition Process</b></i><i> – </i>as defined in Section 7.04.</p>\n<p class=\"deflist\"><i><b>FF&amp;E</b></i> - all fixtures, furniture, furnishings and equipment (not including Operating Equipment and Operating Supplies) required for the operation of the Building as a Property in accordance with the standards set forth in this Agreement including, without limitation, (i) office furnishings and equipment, and (ii) specialized Property equipment necessary for the operation of any portion of the Building, including, public rooms, parking spaces, and recreational facilities</p>\n<p class=\"deflist\"><i><b>Fiscal Year</b></i> - the calendar year from January 1 to December 31, unless and until Owner and Manager otherwise mutually agree in writing, which agreement shall be attached hereto and incorporated herein where applicable.</p>\n<p class=\"deflist\"><i><b>Fitch</b></i> – Fitch IBCA, Inc. and its successors in interest.</p>\n<p class=\"deflist\"><i><b>Fixed Charges</b></i> – those costs and expenses of the Property which are expressly excluded from Operating Costs, including the following:</p>\n<p class=\"ind\">(i)\ttaxes and assessments in respect of the real or personal property located at the Property; and</p>\n<p class=\"ind\">(ii)\tthe payment of interest on loans approved by Owner; and</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 1</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFINITIONS (cont'd)</h3>", body: "<p class=\"ind\">(iii)\trental payments or payments for purchase options under leases of equipment which are capital leases under the Uniform System of Accounts.</p>\n<p class=\"deflist\"><i><b>Force Majeure</b></i> – as defined in Section 16.01.</p>\n<p class=\"deflist\"><i><b>Force Majeure Cessation</b></i> – as defined in Section 16.01.</p>\n<p class=\"deflist\"><i><b>GAAP </b></i>- generally accepted accounting principles, consistently applied.</p>\n<p class=\"deflist\"><i><b>Index</b></i> - the Consumer Price Index for All Urban Consumers (1982-84 = 100) as published by the United States Bureau of Labor Statistics [U.S. City Average], as amended.  If the compilation and/or publication of such Index shall be discontinued or transferred to any other governmental department or bureau or agency, Manager shall (subject to Owner’s approval, which shall not be unreasonably withheld) fix an alternate index or method to implement the parties’ intention that the purchasing power of the amounts to be adjusted by reference to the Index (as hereinafter provided in this Agreement) shall be the same as the purchasing power of the stated amounts as of the Commencement Date.  Likewise, if such Index shall be modified as to components, computing methods or otherwise, then Manager may (subject to Owner’s approval, which shall not be unreasonably withheld) fix an alternate index or method, as aforesaid, or Manager may utilize an appropriate conversion factor so as to achieve substantially the same result as would have been obtained if the Consumer Price Index in effect and as computed, calculated and constituted on the Commencement Date were still then in effect.</p>\n<p class=\"deflist\"><i><b>Interested Persons</b></i> – as defined in Section 17.04.</p>\n<p class=\"deflist\"><i><b>Licenses</b></i> – as defined in Section 5.01.</p>\n<p class=\"deflist\"><i><b>Losses</b></i> – as defined in Section 9.01(b).</p>\n<p class=\"deflist\"><i><b>Management Fee</b></i> - the  Management Fee payable to Manager, as set forth in Article 3.</p>\n<p class=\"deflist\"><i><b>Manager</b></i><i><b>’</b></i><i><b>s Representative</b></i> –as Manager may designate from time to time by notice to Owner. </p>\n<p class=\"deflist\"><i><b>Net Operating Income</b></i> – Total Revenues less the aggregate of Operating Costs, Fixed Charges and Ownership Costs.</p>\n<p class=\"deflist\"><i><b>Non-Defaulting Party</b></i> – as defined in Section 11.02(a).</p>\n<p class=\"deflist\"><i><b>Operating Budget</b></i> – as defined in Section 6.02(b).</p>\n<p class=\"deflist\"><i><b>Operating Costs</b></i> - the entire cost and expense of maintaining, operating and supervising the operation of the Property, excluding Fixed Charges.  Operating Costs shall be the sum of such costs and expenses which are normally charged as a cost of operation under GAAP and the Uniform System of Accounts, excluding Fixed Charges, and including, without limitation, the following:</p>\n<p class=\"ind\">(i)\tthe cost of Operating Supplies and Operating Equipment;</p>\n<p class=\"ind\">(ii)\twages, salaries, employee benefits, payroll taxes, relocation expenses and other costs related to employees at the Property;</p>\n<p class=\"ind\">(iii)\tadvertising and promotional expenses incurred directly by the Property;</p>\n<p class=\"ind\">(iv)\tadministrative and general expenses of the Property;</p>\n<p class=\"ind\">(v)\tutility and energy costs;</p>\n<p class=\"ind\">(vi)\toperating licenses and permits;</p>\n<p class=\"ind\">(vii)\tgrounds and landscaping maintenance costs;</p>\n<p class=\"ind\">(viii)\tall expenditures made for routine maintenance and repairs to keep the Property in good condition and repair;</p>\n<p class=\"ind\">(ix)\tapplicable insurance premiums for the insurance coverages described in Exhibit A;</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 1</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFINITIONS (cont'd)</h3>", body: "<p class=\"ind\">(x)\tthe  Management Fee provided for in Section 3.01 and Close-Out Fee as provided in Section 3.03, if applicable;</p>\n<p class=\"ind\">(xi)\tthe cost of third party accounting fees, payroll services and legal fees for services directly related to the operation of the Property and its facilities;</p>\n<p class=\"ind\">(xii)\tReimbursed Expenses;</p>\n<p class=\"ind\">(xiii)\treasonable increases in reserves for uncollectible accounts receivable as set forth in the Proposed Annual Plan and Approved Budget, but not limited to the amounts set forth in such Proposed Annual Plan and Approved Budget</p>\n<p class=\"deflist\"><i><b>Operating Equipment</b></i> - all operating equipment required for the operation of the Property.</p>\n<p class=\"deflist\"><i><b>Operating Supplies</b></i> - all consumable items used in the operation of the Property, fuel, soap, cleaning materials, tenant or invitees amenities, paper supplies, and all other similar items.</p>\n<p class=\"deflist\"><i><b>Operating Term</b></i> – as defined in Section 2.02(a).</p>\n<p class=\"deflist\"><i><b>Operational Standards</b></i> – as defined in Section 4.01.</p>\n<p class=\"deflist\"><i><b>Owner</b></i><i><b>’</b></i><i><b>s Report</b></i> – as defined in Section 6.01(e).</p>\n<p class=\"deflist\"><i><b>Owner</b></i><i><b>’</b></i><i><b>s Representative</b></i> –CWCAM employee.  VP or higher or such other person as Owner may designate from time to time by notice to Manager.</p>\n<p class=\"deflist\"><i><b>Ownership Costs</b></i> - those costs not directly related to the operation of the Property, including, but not limited to:</p>\n<p class=\"ind\">\t\t(i)\tdebt service (interest and principal) on any Permitted Mortgage;</p>\n<p class=\"ind\">\t\t(ii)\trental payments pursuant to any existing ground lease or installment sales contracts approved by Manager, including all charges for common area maintenance or owners’ association dues;</p>\n<p class=\"ind\">(iii)\trental payments pursuant to any capital leases approved by Owner;</p>\n<p class=\"ind\">\t\t(iv)\tother recurring and non-recurring ownership costs, such as Owner’s entity administration and servicing costs; and</p>\n<p class=\"ind\">\t\t(vi)\tsuch other cash expenditures (including Capital Expenditures), which are normally treated as a capital expenditure under GAAP.</p>\n<p class=\"deflist\">[Intentionally Omitted].</p>\n<p class=\"deflist\"><i><b>Permitted Mortgage</b></i> – any mortgage, deed of trust or other instrument conveying an interest in or encumbering the Property or any part thereof or any interest therein to secure any indebtedness, obligation or other liability of Owner or any other person or entity, which mortgage, deed of trust or other instrument shall have been approved and consented to by Owner in the exercise of its sole discretion.</p>\n<p class=\"deflist\"><i><b>Preliminary Operating Budget</b></i> – as defined in Section 6.02(a).</p>\n<p class=\"deflist\"><i><b>Property</b></i> – a collective term for the Site, the Building, the FF&amp;E, the Operating Equipment and the Operating Supplies.</p>\n<p class=\"deflist\"><i><b>Proposed Annual Plan</b></i> – as defined in Section 6.02(b).</p>\n<p class=\"deflist\"><i><b>PSA</b></i> – the Pooling and Servicing Agreement dated as of ___________, for the registered holders of __________________________, Commercial Mortgage Pass-Through Certificates, Series ____________.  </p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 1</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFINITIONS (cont'd)</h3>", body: "<p class=\"deflist\"><i><b>Qualified Insurer</b></i> – In the case of (i) all policies not referred to in clause (ii) below, an insurance company or security or bonding company qualified to write the related insurance policy in the relevant jurisdiction and whose claims paying ability is rated (x) in one of the three highest applicable rating categories by at least two nationally recognized statistical rating organizations (one of which must be S&amp;P), and (y) either “A” by Fitch or at least A-IX by Best’s Rating Guide, and (ii) in the case of the fidelity bond and the errors and omissions insurance required to be maintained pursuant to Special Stipulation J, shall have a claim paying ability rated by S&amp;P and Fitch (and if such company is not rated by Fitch, is rated A-IX by Best’s Key Rating Guide) no lower than two ratings categories (without regard to pluses or minuses) lower than the highest rating of any outstanding Class of Certificates issued pursuant to the PSA from time to time, but in no event lower than “BBB” by Fitch and S&amp;P unless in the case where such insurance is not rated by S&amp;P and/or Fitch or where such insurance has a claims paying ability rated by S&amp;P and/or Fitch in a rating category lower than required herein, either (a) such insurer’s obligations are guaranteed or backed by a company having such a claim-paying ability rating, or (b) each of S&amp;P and/or Fitch has confirmed in writing that obtaining the related insurance from and insurance company that is not rated by such rating agency (subject to the foregoing exceptions) or that has a lower claims paying ability than such requirements shall not result, in and of itself, in a downgrade, qualification or withdrawal of the then current ratings by such rating agency to any Class of Certificates issued pursuant to the PSA.</p>\n<p class=\"deflist\"><i><b>Reimbursed Expenses</b></i> – as defined in Section 6.04.</p>\n<p class=\"deflist\"><i><b>REMIC Requirements</b></i> – as defined in Paragraph R of Exhibit B attached.</p>\n<p class=\"deflist\"><i><b>Reserve Fund</b></i> – amounts set forth in a line item in the Excess Cash Worksheet showing detailed estimates of monthly expenditures for the ensuing Fiscal Year (or Fiscal Year ________  for the first Operating Budget) covering capital expenditures.</p>\n<p class=\"deflist\"><i><b>S&amp;P</b></i> – Standard &amp; Poor’s Rating Services, a division of McGraw-Hill Companies, Inc., or its successors in interest.</p>\n<p class=\"deflist\"><i><b>Security Deposit Account</b></i> – as defined in Section 6.03(c).</p>\n<p class=\"deflist\"><i><b>Site</b></i> – the land described in Exhibit C.</p>\n<p class=\"deflist\"><i><b>Total Revenues</b></i> - all revenues and income of any nature derived directly or indirectly from the Property or from the use or operation thereof, including revenues, rental or other payments from lessees and sublessees (but not the gross receipts of such lessees and sublessees), and the proceeds of business interruption, use, occupancy or similar insurance.  Total Revenues shall be determined in accordance with GAAP.</p>\n<p class=\"body\">\tThe calculation of Total Revenues shall exclude the following:  (i) any proceeds from the sale or other disposition of the Property, or other capital assets; (ii) any interest received or accrued with respect to the Reserve Fund, the Bank Account or any other deposit or investment of Property funds; (iii) any fire and extended coverage insurance proceeds; (iv) any condemnation awards; and (v) any proceeds of financing or refinancing of the Property.</p>\n<p class=\"deflist\"><i><b>Uniform System of Accounts</b></i> – accounting standards used to provide uniformity and consistency in reporting financial information, as detailed in CFR, Title 18 – Parts 1-399.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 2</h2>", subtitleHtml: "<h3 class=\"art-sub\">TERM AND EXTENSIONS</h3>", body: "<p class=\"body\"><b>2.01</b><b>\tCommencement Date.</b></p>\n<p class=\"body\">The commencement date (the “<i><b>Commencement Date</b></i>”) of the Term hereunder shall be the date filled in by Owner below Owner’s signature on the signature page to this Agreement.</p>\n<p class=\"body\"><b>2.02</b><b>\tTerm.</b></p>\n<p class=\"ind\">(a)\tThis Agreement shall have a term (the <i>“</i><i><b>Operating Term</b></i>”) commencing on the Commencement Date and expiring on the first anniversary of the Commencement Date (the “<i><b>Expiration Date</b></i>”), unless sooner terminated in accordance with the provisions of this Agreement.  This Agreement shall automatically terminate upon a sale of the Property, unless assigned to the purchaser pursuant to Section 15.01(b), Owner being under no obligation to so assign same.  This Agreement shall automatically be extended for consecutive one-year renewal terms (each such renewal term to commence on the day immediately following the last day of the then-expiring term), at the same terms herein, until such time as either party terminates in accordance with this Agreement (the <i>“</i><i><b>Extension Periods</b></i><i>”</i><i>)</i>.  </p>\n<p class=\"ind\">(b) Notwithstanding anything to the contrary contained herein: (i) Owner may terminate this Agreement with or without cause, prior to the expiration of the Operating Term or any Extension Periods upon at least thirty (30) days’ prior written notice to Manager, and without the payment of any early termination fee or other penalty of any kind; and (ii) Manager may terminate this Agreement with or without cause, prior to the expiration of the Operating Term or any Extension Periods upon at least sixty (60) days’ prior written notice to Owner, and without the payment of any early termination fee or other penalty of any kind.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 3</h2>", subtitleHtml: "<h3 class=\"art-sub\">MANAGEMENT FEES AND PAYMENTS TO MANAGER  &amp; OWNER</h3>", body: "<p class=\"body\"><b>3.01</b><b>\tManagement Fee.</b></p>\n<p class=\"body\">In consideration of the management of the Property by Manager, Owner agrees to pay to Manager the Management Fee. The &#8220;Management Fee&#8221; shall mean and refer to a fee equal to <b>%%MANAGEMENT_FEE_TEXT%%</b> of Total Revenues with respect to each month (or portion thereof) during the Term of this Agreement. The Management Fee for the immediately preceding month shall be paid monthly to Manager from the Bank Account.</p>\n<p class=\"body\"><b>3.02</b><b>\tConstruction Management Fee.</b></p>\n<p class=\"body\">In the event Manager oversees major projects (i.e., projects in excess of $5,000.00 in total costs), including the design, planning, coordination, vendor selection and material selection, at the Property, Manager shall be entitled to the Construction Management Fee set forth in the following paragraph (the “<i><b>Construction Management Fee</b></i>”), payable to Manager upon Owner’s final approval and payment of such construction costs.  Manager shall only be entitled to the Construction Management Fee for specific projects for which Manager has received Owner’s express, prior written agreement and approval.  Notwithstanding anything contained herein to the contrary, Manager shall not be entitled to a Construction Management Fee in connection with any work related to a casualty or condemnation at the Property, unless approved by Owner as part of the Capital Improvement Approval Form.  For the purposes of determining Manager’s Construction Management fee, the total costs of construction shall be determined exclusively by the costs actually incurred as a result of construction. </p>\n<p class=\"body\">Manager’s Construction Management Fee shall be as follows:</p>\n<p class=\"ind\">1.\tIf the total cost of the construction is $5,000.00 or less, there shall be no Construction Management Fee.</p>\n<p class=\"ind\">2.\tIf the cost of construction is $5,001.00 or greater but less than or equal to $500,000.00, then the Manager shall receive a Construction Management Fee equal to six percent (6%) of the hard and soft costs of construction.</p>\n<p class=\"ind\">3.\tIf the cost of construction is $500,001.00 or greater but less than or equal to $750,000.00, then Manager shall receive a Construction Management Fee equal to: (i) six percent (6%) of the hard and soft costs of construction up to $500,000.00; plus (ii) five percent (5%) of the hard and soft costs of construction between $500,001.00 and $750,000.00.</p>\n<p class=\"body\">4.\tIf the cost of construction is $750,001.00 or greater but less than or equal to $1,000,000.00, then Manager shall receive a Construction Management Fee equal to: (i) six percent (6%) of the hard and soft costs of construction up to $500,000.00; plus (ii) five percent (5%) of the hard and soft costs of construction between $500,001.00 and $750,000.00; plus (iii) four percent (4%) of the hard and soft costs of construction between $750,001.00 and $1,000,000.00.</p>\n<p class=\"body\">5.\tIf the cost of construction is $1,000,001.00 or greater, then Manager shall receive a Construction Management Fee equal to: (i) six percent (6%) of the hard and soft costs of construction up to $500,000.00; plus (ii) five percent (5%) of the hard and soft costs of construction between $500,001.00 and $750,000.00; plus (iii) four percent (4%) of the hard and soft costs of construction between $750,001.00 and $1,000,000.00; plus (iv) three percent (3%) of the hard and soft costs of construction above $1,000,000.00.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 3</h2>", subtitleHtml: "<h3 class=\"art-sub\">MANAGEMENT FEES AND PAYMENTS TO MANAGER  &amp; OWNER (cont'd)</h3>", body: "<p class=\"body\">Owner shall pay all costs incurred in the construction management services by Manager, including the payment of all architects, engineers, designers, space planners, general contractors, and subcontractors hired by Manager, on behalf of Owner, as are reasonably necessary to complete the construction, repairs, or renovations required at the Property and which have been approved in writing by Owner, provided, however, that Manager shall disclose to Owner if any of such architects, engineers, designers, space planners, general contractors, and subcontractors are also Affiliates of Manager prior to retaining the services of such parties.  All applications for payment from Owner shall be on a form approved by Owner and with such back-up as Owner may reasonably request.  The above Construction Management Fee shall be included as part of the Management Fee. </p>\n<p class=\"body\"><b>3.03</b><b>\t</b><b>One Time Close-Out </b><b>Fee</b>.</p>\n<p class=\"body\">Upon termination of this Agreement after a sale of the Property, provided that there is then no Event of Default (hereinafter defined) by Manager, Owner agrees to pay to Manager a one-time close out fee amount equal to the Management Fee (calculated as stated in Section 3.01) attributable to the calendar month in which the closing of the sale of the Property takes place (the “<i><b>Close-Out Fee</b></i>”). Close-Out Fee is in consideration for Manager complying with the Disposition Process and shall be paid from the Bank Account within three (3) days after the sale of the Property.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 4</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATIONAL STANDARDS</h3>", body: "<p class=\"body\"><b>4.01</b><b>\tOperational Standards.</b></p>\n<p class=\"body\">Manager covenants to and shall operate the Property in accordance with the terms of this Agreement and the operational standards developed by Manager in connection with its property management business, as such operational standards are modified, revised or amended from time to time (the “<i><b>Operational Standards</b></i>”).  Owner shall cooperate with Manager throughout the Term (as the same may be extended) so that Manager shall be able to operate the Property in accordance with the Operational Standards.  Manager may make such changes to the Operational Standards during the Term of this Agreement as are reasonable for the operation of the Property.  Manager will not, without Owner’s prior written approval, make any Capital Expenditures or make any structural changes to the Property, except as permitted in Section 4.03 below.</p>\n<p class=\"body\"><b>4.02</b><b>\tManager &amp; Owner Control.</b></p>\n<p class=\"ind\">(a)\tThe operation of the Property shall be under the exclusive supervision and control of Manager, who shall be responsible for the proper and efficient operation of the Property in accordance with the standards set forth in this Agreement.  Manager shall have the right, subject to the provisions of this Agreement, to determine operating policy, standards of operation, and any other matters affecting customer relations or the efficient management and operation of the Property, including, without limitation, the use of space therein.  Without limiting the foregoing, Manager shall have the right, with Owner’s approval, and subject to the other provisions of this Agreement, to determine policies relating to labor policies, credit policies, receipt, holding and disbursement of funds, maintenance of bank accounts, and the procurement of inventories, supplies and services, promotion, and the use of other Property facilities by existing or potential customers, invitees, or tenants<b>.</b> Additionally, Manager shall collect rents and other payments set forth in this Agreement and supervise and conduct leasing activities on the Property, including, without limitation, showing the Property to prospective tenants, negotiating leases and executing leases on behalf of the Owner subject, however, in all instances to Owner’s leasing guidelines as provided to Manager on a weekly basis as part of the meetings and conference calls as described in Section 4.04 below and during the annual budget meetings.</p>\n<p class=\"ind\">(b)\tExcept in connection with tenant eviction or rent collection proceedings, Manager shall not engage legal counsel or prosecute legal claims relating to the Property without Owner’s prior written consent, which consent may be withheld in Owner’s sole and absolute discretion.</p>\n<p class=\"body\"><b>4.03</b><b>\tContractual Authority.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 4</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATIONAL STANDARDS (cont'd)</h3>", body: "<p class=\"body\">Subject to the limitations contained elsewhere in this Agreement, Manager is and shall be authorized to make, enter into and perform in the name of, for the account of, and on behalf of Owner, as an Operating Cost, any operating contracts and agreements deemed reasonably necessary by Manager to carry out and place in effect the terms and conditions of this Agreement, including the execution by Manager in Owner’s name of equipment leases and the like relating to the Property.  Notwithstanding anything to the contrary in the foregoing, Manager shall not, without Owner’s prior written approval, execute any contract in Owner’s name which (a) is not provided for in the Approved Budget; (b) extends beyond one year; (c) is not cancelable by Owner without penalty upon termination of this Agreement or upon thirty (30) days’ notice or less; (d) involves Capital Expenditures, unless approved as part of the Capital Expenditures Budget or on the Capital Improvement Approval Form; or (e) provides for aggregate payments by Owner over the life of the contract (taking into account Owner’s early termination rights, if any) in excess of $5,000.00, unless approved as part of the Capital Expenditures Budget or on the Capital Improvement Approval Form.</p>\n<p class=\"body\"><b>4.04</b><b>\tMeetings.</b></p>\n<p class=\"body\">Unless otherwise agreed to by the parties, Owner’s Representative and Manager’s Representative, shall meet or convene by telephonic conference call weekly to discuss the operations of the Property.  Meetings with respect to the Property shall not be held more frequently than monthly unless scheduled by Owner.  Such meetings shall be held at the Property or with the agreement of the parties at the Manager’s office or any other location, as mutually agreed upon by the parties or may be convened by telephonic conference call.  At each such meeting, the parties will include a review  of the following: (i) results of operations; (ii) Capital Expenditures; (iii) Proposed Annual Plan; and (iv) any variations from the Approved Budget.  Upon Owner’s request, minutes shall be prepared by Manager as to each such meeting and circulated thereafter to Owner for review and verification.  Such minutes shall be in summary form and shall refer only to the agenda items discussed and the decisions and actions agreed to be taken with respect to such agenda items.</p>\n<p class=\"body\"><b>4.05</b><b>\tProperty Condition Checklist.</b></p>\n<p class=\"body\">Manager shall complete Owner’s risk management checklist (“<i><b>RMC</b></i>”) within thirty (30) days of assuming control of the Property and forward the completed RMC to Owner’s risk management department for review.  Owner’s risk management requirements may vary from time to time for different types and characteristics of Property, and the then current RMC for the Property will be provided to Manager upon Manager’s request after execution of this Agreement.  By completing the RMC Manager represents that it has reasonably reviewed the physical condition of the Property as reflected in the completed RMC and that controls are in place as reflected on the RMC.  Where needed or appropriate experts will be engaged by the Manager, after Owner’s approval and at Owner’s expense, to assist in evaluating risk conditions at the Property.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 5</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATION OF THE PROPERTY</h3>", body: "<p class=\"body\"><b>5.01</b><b>\tLicenses.</b></p>\n<p class=\"body\">Owner warrants that to its actual knowledge there will be no covenants or restrictions which would prohibit or limit Manager, provided that the necessary licenses and permits (the “<i><b>Licenses</b></i>”) therefor have been obtained, from operating the Property, in accordance with Operational Standards.  In cooperation with Owner, Manager or an Affiliate of Manager shall apply for, process, and take all necessary steps to procure (in Manager’s name, and/or Owner’s name to the extent required by local authorities), as an Operating Cost, all Licenses required for the operation of the Property.  Owner agrees to assist Manager in connection with Manager’s efforts to obtain any such Licenses.  Manager undertakes to comply with any conditions set out in any such Licenses and at all times to operate and manage the Property in accordance with such conditions and any other legal requirements.  Upon the expiration or sooner termination of this Agreement, Manager agrees, to the extent permitted by applicable law, to sell, assign, transfer and convey to Owner or its designee all of Manager’s right, title and interest in and to all such Licenses, without charge (other than any expenses of transfer, which shall be Reimbursed Expenses), or (in the event such assignment is not permitted by applicable law) to use reasonable efforts to provide Owner or Owner’s designee with the use and benefits of such Licenses until such time (not to exceed one hundred eighty (180) days) as Owner and/or its designee are able to obtain new Licenses.</p>\n<p class=\"body\"><b>5.02</b><b>\tOperating Equipment and Operating Supplies.</b></p>\n<p class=\"body\">Manager shall procure, in an economical manner, as an Operating Cost all Operating Supplies and Operating Equipment as Manager deems necessary to the normal and ordinary course of operation of the Property and to operate the Property in accordance with the Operational Standards.  Manager shall use its good faith reasonable efforts to qualify for cash and trade discounts, refunds, credits, concessions and other incentives available, and such discounts, refunds, credits, concessions or other incentives shall be applied toward reduction of Operating Costs.  All Operating Supplies and Operating Equipment purchased as an Operating Cost shall be the property of Owner.</p>\n<p class=\"body\"><b>5.03</b><b>\tPersonnel.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 5</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATION OF THE PROPERTY (cont'd)</h3>", body: "<p class=\"ind\">(a)\tAll personnel employed at the Property at all times shall be the employees of Manager or of an Affiliate of Manager. As deemed necessary by Manager and approved by Owner, other employees of Manager or an Affiliate of Manager may be assigned temporarily or on a part-time basis to perform services at the Property, and the allocable portion of such temporary or part-time employee’s salary (including employee benefits) while performing services at the Property, and reasonable expenses incurred by such employee in traveling to and from the Property, will be reimbursed to Manager by Owner, as an Operating Cost.  Subject to the Operational Standards, Manager shall have absolute discretion to hire, fire, promote, supervise, direct and train all employees at the Property, to fix their compensation and benefits, and generally to establish and maintain all policies relating to employment and employment benefits.   All costs of every kind and nature pertaining to all employees at the Property (excluding any supervisory or executive personnel) arising out of the employer-employee relationship, including, without limitation, salaries, benefits (including vacation, sick and personal days and accruals at the accrual rate established by Manager), relocation costs, costs incurred in connection with governmental laws and regulations and insurance roles, and such other expenses as Manager, in its reasonable discretion and after receipt of written approval from Owner, may deem appropriate shall be an Operating Cost, unless caused or related to Manager’s breach of this Agreement or by Manager’s negligence, willful misconduct, fraud or actions beyond the scope of the authority granted to Manager under this Agreement, in which event such costs, expenses, losses and damages shall be paid solely by Manager from its own funds.  Manager’s overhead, office or administrative expenses and salaries relating to Manager’s employees not employed at the Property shall not be reimbursed.  </p>\n<p class=\"ind\">(b)\tOwner will use reasonable efforts to cause the entity which shall succeed Manager as the operator of the Property to hire a sufficient number of the employees at the Property to avoid the occurrence, in connection with the termination, of a “closing” under the Worker Retraining and Notification Act of 1990 (as amended, the <i>“</i><i><b>WARN Act</b></i><i>”</i>).</p>\n<p class=\"body\"><b>5.04</b><b>\tRoutine Maintenance and Repairs.</b></p>\n<p class=\"body\">Subject to the availability of sufficient funds therefor, and in accordance with the Approved Budget, Manager shall maintain the Property in good repair and condition and in conformity with the Operational Standards, and applicable laws and regulations, and shall make or cause to be made such routine maintenance, repairs and minor alterations, the cost of which can be expensed under GAAP, as Manager, from time to time, deems necessary for such purposes and in order for the Property to maintain a competitive position.  The reasonable cost of such routine maintenance, repairs and alterations shall be paid from Total Revenues and shall be treated as an Operating Cost; to the extent that Property revenues are insufficient therefor, Owner shall, upon Manager’s request, provide sufficient funds to pay for such costs when due.  Expenditures under this Section 5.04 shall not be paid from the Reserve Fund.  The determination of whether an expenditure is for routine repairs and maintenance under this Section 5.04 or, in the alternative, a Capital Expenditure (as defined below) under Section 5.05 shall be made in accordance with this Agreement, GAAP, and the Uniform System of Accounts.</p>\n<p class=\"body\"><b>5.05</b><b>\tCapital Expenditures.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 5</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATION OF THE PROPERTY (cont'd)</h3>", body: "<p class=\"body\">Manager shall not make Capital Expenditures in excess of $5,000.00 without Owner’s prior written consent as evidenced by Owner’s execution of the Capital Improvement Approval Form, which consent may be withheld in Owner’s sole and absolute discretion.   The determination as to whether the expenditure is a Capital Expenditure will be made in accordance with GAAP.  As used herein, “<i><b>Capital Expenditures</b></i>” shall mean and include repairs, replacements, alterations, renewals and improvements to the Property which are normally capitalized under GAAP, including, without limitation, those items defined as FF&amp;E repairs, alterations, improvements, renewals or replacements to the Building’s structure or to its mechanical, electrical, heating, ventilating, air conditioning, plumbing or vertical transportation systems, exterior and interior repainting, and resurfacing building walls, floors, roofs and parking areas and expenditures for any computer and communications hardware, and related labor expenses.</p>\n<p class=\"body\"><b>5.06</b><b>\tEmergency Repairs: Repairs Required by Law.</b></p>\n<p class=\"ind\">(a)\tIn the event a condition should exist in, on or about the Property of an emergency nature, which condition requires immediate action to preserve and protect the Property, to assure its continued operation without impacting Manager’s forecasted Total Revenues (as set forth in Article 1 and reported in the Owner’s Report) by more than five percent (5%) over a period of thirty (30) days, or to protect Property guests or employees, Manager shall give Owner prompt notice thereof by telephone and e-mail and shall make reasonable efforts to secure Owner’s prior approval of any actions which Manager proposes to take and of any expenditures which Manager deems necessary to repair and correct such condition.  However, in the event of an emergency which requires immediate action and/or repairs to prevent further damage to the Property or to protect Property guests or employees, and Owner is not readily available for consultation, Manager shall be authorized to use its reasonable commercial judgment regarding same and on behalf of and at the sole cost and expense of Owner, is authorized to take such steps and to make such expenditures necessary to repair and correct any such condition, whether or not provisions have been made in the Approved Budget for any such emergency expenditures; provided, in such event, Manager shall notify Owner of any such emergency expenditures by the end of the business day next following such emergency and shall provide to Owner invoices reflecting such emergency expenditures.  It is understood and agreed that any action taken by Manager under this Section 5.06(a) in connection with any particular emergency condition shall not create precedent or a duty on the part of Owner or Manager to take any action with respect to any future event.  Expenditures under this Section 5.06(a) shall be paid from the Bank Account or, if necessary, by Owner, unless such expenditures were caused by or resulted from Manager’s negligence, willful misconduct, fraud, breach of this Agreement or actions beyond the scope of the authority granted to Manager under this Agreement, in which event, the cost of such expenditures shall be paid by Manager from its own funds.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 5</h2>", subtitleHtml: "<h3 class=\"art-sub\">OPERATION OF THE PROPERTY (cont'd)</h3>", body: "<p class=\"ind\">(b)\tIn the event that, at any time during the Term, repairs to or additions, changes or corrections in the Property of any nature shall be required by reason of any laws, ordinances, rules or regulations now or hereafter in force, or by order of any governmental or municipal power, department, agency, authority or officer, whether such repairs, etc. are Capital Expenditures or otherwise, Manager shall give Owner prompt notice thereof by telephone and email transmission and shall secure Owner’s prior approval of any actions which Manager proposes to take and of any expenditures which Manager deems necessary to comply with such laws, ordinances, rules, regulations or such order of any governmental or municipal power, department, agency, authority or officer.  Upon obtaining Owner’s approval, Manager shall make such repairs, additions, changes or corrections which shall be paid for from the Bank Account or, if necessary, by Owner: (i) unless (and except for so long as) compliance therewith is in good faith being contested by Owner and enforcement is stayed in a manner reasonably satisfactory to Manager; or (ii) unless such required repairs to or additions, changes or corrections in the Property were caused by or resulted from Manager’s negligence, willful misconduct, fraud, breach of this Agreement or actions beyond the scope of the authority granted to Manager under this Agreement, in which event the costs of such required repairs to or additions, changes or corrections in the Property shall be paid by Manager from its own funds.</p>\n<p class=\"body\"><b>5.07</b><b>\tVacant Properties.</b>  During any period of time that the Property is vacant, Manager shall cause the following requirements to be met:</p>\n<p class=\"ind\">(a)\tManager shall ensure that all apartments within the Property are secured and locked (other than leased apartments which are occupied by the applicable tenant, which shall be the responsibility of such tenant(s));</p>\n<p class=\"ind\">(b)\tFire systems for each building (and within each apartment) at the Property shall be in good working order and activated;</p>\n<p class=\"ind\">(c)\tHeat in all apartments within the Property shall be maintained to at least 55 degrees Fahrenheit (other than leased apartments which are occupied by the applicable tenant, which shall be the responsibility of such tenant(s)); and</p>\n<p class=\"ind\">(d)\tManager shall either occupy a management office at the Property or engage third party security for the Property (which may be a scheduled security guard patrol in marked vehicles or on-site security, as reasonably determined based upon crime statistics at the Property and the surrounding area).</p>\n<p class=\"body\">For purposes of this Section 5.07, “<i><b>vacant</b></i>” means seventy percent (70%) or more of the square footage of the buildings on the entire Property is unoccupied (whether or not leased, and without regard as to whether same is temporary (other than <i>de minim</i><i>i</i><i>s</i> closures) or permanent, and whether or not the cause of such vacancy is fire, flood, use as model units, or any other cause).  </p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 6</h2>", subtitleHtml: "<h3 class=\"art-sub\">FISCAL MATTERS</h3>", body: "<p class=\"body\"><b>6.01</b><b>\tAccounting Matters.</b></p>\n<p class=\"ind\">(a)\tManager shall maintain an accurate accounting system, with its management of the Property.  The books and records reflecting the Property operations shall be maintained at the Property, at the principal office of Manager or at a regional accounting office, at Manager’s option; provided that Manager shall give notice to Owner of the location of such books and records.</p>\n<p class=\"ind\">(b)\tOwner, and the independent accounting firms of Owner, shall each have the right and privilege of examining said books and records at any reasonable time during normal business hours following twenty-four hours (24) advance notice to Manager, unless Manager shall be in default under this Agreement, in which case no advance notice to Manager shall be required.  Any such review shall be completed without material disruption to the Property operations.</p>\n<p class=\"ind\">(c)\tUpon request of Owner, a certified audit of the Property operations shall be performed by a Certified Public Accounting firm as approved and appointed by Owner.  Manager shall cooperate in good faith with Owner and its representatives to facilitate such audit.</p>\n<p class=\"ind\">(d)\tIf any such audit prepared pursuant to Section 6.01(b) discloses an overcharge of any Management Fee for the period covered by the audit by ten percent (10%) or more, then the expense of such audit shall be an expense of Manager which Manager, from its own funds, shall pay to Owner immediately upon demand by Owner.  In addition, if any such audit discloses a deficiency in the amount of funds which should have been turned over by Manager to Owner during the period covered by such audit by more than five percent (5%), then (i) Manager shall immediately, upon demand by Owner, pay from Manager’s funds the amount of such deficiency to Owner; and (ii) the expense of such audit shall be an expense of Manager which Manager, from its own funds, shall pay to Owner immediately upon demand by Owner.  If Manager does not pay to Owner any such overcharge on such deficiency or the cost of an audit required to be paid by Manager within ten (10) days after demand is made therefor by Owner, such failure shall be an Event of Default under the terms of this Agreement entitling Owner, at its election, to immediately terminate this Agreement and entitling Owner to receive interest at the rate of twelve percent (12%) on the unpaid amount.</p>\n<p class=\"ind\">(e)\tManager shall prepare and furnish to Owner, within fifteen (15) calendar days after the end of each calendar month, financial statements for the Property setting forth the financial position and results of operations of the Property for such calendar month and the calendar year-to-date with variations from the Approved Budget identified and with comparisons to the then current Operating Budget and the previous year’s results if the previous year results have been prepared by Manager or provided to Manager in an acceptable form (collectively, the “<i><b>Owner</b></i><i><b>’</b></i><i><b>s Report</b></i>”).  Manager shall also provide Owner with additional operating and financial data as Owner may reasonably request; the cost of providing said data to be an Operating Cost of the Property.</p>\n<p class=\"ind\">(f)\tManager shall prepare and furnish to Owner, on a weekly basis, written reports setting forth the operations of the Property for each such week, which reports shall be in a form approved by Owner.</p>\n<p class=\"body\"><b>6.02</b><b>\t</b><b>Proposed Annual Plan.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 6</h2>", subtitleHtml: "<h3 class=\"art-sub\">FISCAL MATTERS (cont'd)</h3>", body: "<p class=\"ind\">(a)\t<b>Preliminary Operating Budget; Estimates of Other Expenditures</b><b>.</b>  Manager shall submit to Owner the Proposed Annual Plan, which shall include a preliminary Operating Budget (a “<i><b>Preliminary Operating Budget</b></i>”) (as set forth in Section 6.02(b) below) within thirty (30) days of the Commencement Date.<b>  </b>Manager shall review the Proposed Annual Plan within thirty (30) days with Owner, and subject to Owner’s approval, which shall not be unreasonably withheld, the Proposed Annual Plan shall become the “<i><b>Approved Budget</b></i>” for such calendar year, and Manager shall implement it.  Owner shall approve the Proposed Annual Plan or state its specific objections thereto (or to any specific item or items therein) after the Proposed Annual Plan is submitted by Manager to Owner.  In the event Owner objects to the Proposed Annual Plan, or any specific line item or items of the Proposed Annual Plan, pending resolution thereof, the Preliminary Operating Budget or the specific line item or items of expense (not revenue) that have not been approved shall be suspended and replaced for the Fiscal Year in question by an amount equal to the amount of such budget item or items in the Preliminary Operating Budget until Owner’s objections are resolved.  Owner and Manager shall use their good faith efforts to resolve Owner’s objections as soon as possible, whereupon such resolution shall be incorporated into the Approved Budget.  </p>\n<p class=\"ind\">(b)\t<b>Operating Budget/Approval</b><b>.</b>  No later than November 1 of each calendar year, Manager shall submit to Owner an annual forecast for the operation of the Property for the immediately following Fiscal Year containing revenue projections and budgets of expenses (the “<i><b>Operating Budget</b></i>”). Manager shall, at the same time, also submit to Owner a Marketing Plan, prepare plans and estimates of the expenditures necessary, in such detail as Owner shall reasonably require, for Capital Expenditures (the “<i><b>Capital Expenditures Budget</b></i>”), the Capital Expenditures Budget which, together with the Operating Budget, will comprise the “<i><b>Proposed Annual Plan</b></i>.”  Manager shall review the Proposed Annual Plan with Owner, and subject to Owner’s approval, the Proposed Annual Plan shall become the “<i><b>Approved Budget</b></i>” and Manager shall implement it during the Fiscal Year.  Owner shall approve the Proposed Annual Plan or state its specific objections thereto (or to any specific item or items therein) after the Proposed Annual Plan is submitted by Manager to Owner.  In the event Owner objects to the Proposed Annual Plan or any specific line item or items of the Proposed Annual Plan prior to commencement of the Fiscal Year in question, pending resolution thereof, the Proposed Annual Plan or the specific line item or items of expense (not revenue) that have not been approved shall be suspended and replaced for the Fiscal Year in question by an amount equal to the amount of such budget item or items for the Fiscal Year prior thereto, adjusted (per item) by the percentage change in the Index over the twelve (12) month period immediately preceding the start of the Fiscal Year in question.  Owner and Manager shall use their good faith efforts to resolve Owner’s objections as soon as possible whereupon such resolution shall be incorporated into such Approved Annual Plan.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 6</h2>", subtitleHtml: "<h3 class=\"art-sub\">FISCAL MATTERS (cont'd)</h3>", body: "<p class=\"ind\">(c)\t<b>Variance from Approved Budget</b><b>.  </b>Manager may, without Owner’s approval, make aggregate expenditures in any Fiscal Year which exceed the Approved Budget, provided that such excess does not exceed by more than ten percent (10%) (the <i>“</i><i><b>10% Limitation</b></i>”) (i) any line item amount in the Approved Budget, or (ii) in the aggregate, all expenditure amounts as provided in the Approved Budget.  Manager may expend in excess of said ten percent (10%) Limitation only under the following circumstances (provided such expenditures are reasonable in nature and are required to satisfy the Operational Standards):</p>\n<p class=\"ind\">(i)\tas the result of increased costs due to increased (A) occupancy rates, (B) market wages, (C) utility costs, or (D) other material increases in Operating Costs beyond the reasonable control of Manager; or</p>\n<p class=\"ind\">(ii)\tas the result of an emergency, as described in Section 5.06, or of expenditures beyond the reasonable control of Manager, such as insurance, real estate taxes, weather related costs, and increases in the cost of utilities based upon changes in utility rates.</p>\n<p class=\"body\">The provisions of this Section 6.02(c) shall operate notwithstanding the provisions of Section 6.02(b) above.  Manager shall promptly notify Owner of any expenditures that have been or are expected to be made in excess of the Approved Budget pursuant to this Section 6.02(c)<b> </b>and of the reasons therefor.  Delivery of an Owner’s Report to Owner will satisfy this notice requirement.</p>\n<p class=\"ind\">(d)\t<b>Revised Budget</b><b>.  </b>In addition to the additional amounts Manager may expend pursuant to Section 6.02(c) above, Owner and Manager acknowledge and agree that there may occur from time to time unpredicted significant changes, variables or events affecting the operation of the Property, including unanticipated changes in occupancy rates, market conditions, or additional unanticipated items of income or expense.  In such event, Manager may request variance(s) from the Approved Budget, which are reasonable and necessary to continue to operate the Property in accordance with the Operational Standards.  Owner’s approval of such a request shall not be unreasonably withheld.  Any such request by Manager shall be submitted to Owner in writing with an explanation thereof and shall be accompanied by supporting information for the request.  If, after consultation with Manager, Owner disapproves of such a request for variance(s) from the Approved Budget, then such variance(s) shall not be incorporated into the Approved Budget.  </p>\n<p class=\"ind\">(e)\t<b>Consultation</b><b>.  </b>At the time of the review by Owner with Manager of the Proposed Annual Plan and at any additional meetings during the Fiscal Year called by Owner and Manager, Manager shall, as necessary, consult with Owner concerning any material changes Manager is contemplating<b> </b>with respect to its policies concerning management of the Property, sales, wage scales, general operating procedures, economics and operation, and other matters affecting the operation of the Property.  Notwithstanding anything herein to the contrary, Manager shall consult with Owner regarding the hiring of sales and management personnel.</p>\n<p class=\"body\"><b>6.03</b><b>\tFunding; Bank Accounts.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 6</h2>", subtitleHtml: "<h3 class=\"art-sub\">FISCAL MATTERS (cont'd)</h3>", body: "<p class=\"ind\">(a)\tOwner will provide all funds from the Commencement Date and throughout the Term as necessary to pay for all Operating Costs, Ownership Costs and Fixed Charges relating to the Property, and to perform and satisfy Owner’s covenants and responsibilities under this Agreement.  The performance of all activities by Manager hereunder shall be on behalf, and for the account, of Owner.  Accordingly, Manager shall be authorized to pay any Operating Costs, Owner’s Costs<b> </b>or Fixed Charges out of the Bank Account.</p>\n<p class=\"ind\">(b)\tManager shall establish (or cause to be established) in the name of Owner, and for Owner’s account, bank accounts (collectively, the “<i><b>Bank Account</b></i>”) for the operation of the Property at a bank or banks approved by Owner into which all funds advanced to the Property by Owner or otherwise derived from the operation of the Property shall be deposited.  The Bank Account shall at all times contain a minimum balance (the “<i><b>Minimum Balance</b></i>”).  The Minimum Balance shall be $5,000.00 (excluding the balance held in any Security Deposit Account (as hereinafter defined).  Thereafter, Owner shall maintain the Minimum Balance in accordance with the terms of Section 7.02 hereof.  The Bank Account shall provide that Owner’s designees and Manager’s designees shall be the only parties authorized to draw upon the Bank Account.  Owner and Manager shall have control of the Bank Account, and any and all monies received from the operation of the Property shall pass through the Bank Account.  Manager agrees to handle such Bank Account as may be required by any Mortgagee, upon reasonable notice from Owner.  Nothing herein contained shall be construed to deprive Manager of the right to maintain petty cash funds at the Property and to make payments therefrom pursuant to the standard practices employed in the industry; provided Manager shall make a complete accounting for the same as required under this Agreement.</p>\n<p class=\"ind\">(c)\t Manager shall establish (or cause to be established) in the name of Owner, and for Owner’s account, a separate Bank Account, which shall be used solely for the purpose of holding any security deposits posted by tenants of the Property (the “<i><b>Security Deposit Account</b></i>”).  Manager shall promptly deposit any Security Deposits received by Manager into the Security Deposit Account and such funds shall not be co-mingled with any other funds.  Manager shall comply with all applicable laws governing the retention and release of any such security deposits.  The Security Deposit Account shall be an interest bearing account, and shall be reflected on the balance sheet for the Property prepared by Manager. The Security Deposit Account shall be designated on such balance sheet as “Cash-Security Deposits”.  Owner shall not fund any unfunded Security Deposit liability arising as a result of a failure of the prior owners or managers to transfer the Security Deposit funds, except as expressly approved by Owner as part of the Operating Budget.</p>\n<p class=\"body\"><b>6.04</b><b>\tReimbursement of Out-of-Pocket Expenses.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 6</h2>", subtitleHtml: "<h3 class=\"art-sub\">FISCAL MATTERS (cont'd)</h3>", body: "<p class=\"body\">It is agreed that Owner shall reimburse Manager and its Affiliates for actual, reasonable and necessary out-of-pocket costs which they shall incur as an Operating Cost in connection with the performance of this Agreement (collectively, the “<i><b>Reimbursed Expenses</b></i>”).  Manager shall have the discretion, exercised reasonably, to determine the necessity for the expenditure of any such amounts, which shall include, without limitation, reasonable travel, meals, lodging, postage, air express, costs of recruitment (including applicable agent’s fee) and other incidental expenses; provided that such Reimbursed Expenses shall be set forth in the Preliminary Operating Budget or the applicable Approved Budget and that none of the foregoing expenses shall be Centralized Services Expenses.  It is agreed that Manager shall be entitled to reimbursement of these expenses directly from the Bank Account at the time incurred.  Such reimbursements shall be in addition to the Management Fee.</p>\n<p class=\"body\"><b>6.05</b><b>\tNon-reimbursable Costs</b><b>.</b></p>\n<p class=\"body\">Except as otherwise permitted in this Article 6, approved by the Owner in writing as an express amendment of this Section of the Agreement or set forth in an Operating Budget submitted by Manager and approved by Owner, the following expenses or costs incurred by or on behalf of Manager in connection with the management and leasing of the Property shall be at the sole cost and expense of Manager and shall not be reimbursed by Owner:</p>\n<p class=\"deflist\">Except as set forth in Section 5.03, cost of gross salary and wages, bonuses, payroll taxes, insurance, workmen’s compensation, and other benefits of Manager’s personnel, or the pro rata share of such costs for personnel; </p>\n<p class=\"deflist\">General accounting and reporting services which are within the reasonable scope of Manager’s responsibility to Owner;</p>\n<p class=\"deflist\">Cost of forms, papers, ledgers, and other supplies and equipment used in Manager’s office;</p>\n<p class=\"deflist\">Cost of electronic data processing equipment, telephone, electronic communication, software costs or any pro rata charge thereon;</p>\n<p class=\"deflist\">Cost of electronic data processing, or any pro rata charge thereof, for data processing provided by computer service companies;</p>\n<p class=\"deflist\">Except as set forth in Sections 5.03 and 6.04, cost of advances made to employees and cost of travel by Manager’s employees or agents to and from the Property;</p>\n<p class=\"deflist\">Employment fees, including advertisement unless specifically approved by Owner in writing;</p>\n<p class=\"deflist\">All interest and penalties for late payments for any kind when the cause thereof is solely related to Manager’s default;</p>\n<p class=\"deflist\">All overhead, office, administrative and general expenses; and</p>\n<p class=\"deflist\">All employee parties, events, travel and recognition, except for holiday parties at the Property for the Manager’s employees.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 7</h2>", subtitleHtml: "<h3 class=\"art-sub\">DISBURSEMENTS</h3>", body: "<p class=\"body\"><b>7.01</b><b>\t</b><b>Disbursement of Funds.</b></p>\n<p class=\"body\">All funds derived from the operation of the Property shall be deposited into the Bank Account created pursuant to the requirements of Section 6.03. There shall in turn be disbursed by Manager for and on behalf of Owner, funds from the Bank Account toward the following items to the extent available (with appropriate reserves established to provide for items payable less frequently than monthly) in the following order of priority, unless directed otherwise by Owner in writing:</p>\n<p class=\"ind\">(a)\tall Operating Costs, including the Management Fee (including the Close-Out Fee) and all Reimbursed Expenses;</p>\n<p class=\"ind\">(b)\tpayment of emergency expenditures as provided under Section 5.06; and</p>\n<p class=\"ind\">(c)      in accordance with Section 7.02 any amounts exceeding the Minimum Balance shall be wired to the Owner on the 15th calendar day of each month. </p>\n<p class=\"body\"><b>7.02</b><b>\tOwner</b><b>’</b><b>s Distribution.</b></p>\n<p class=\"body\">Excess cash shall be disbursed monthly to Owner into the Owner’s operating account (“<i><b>CWCAM REO </b></i><i><b>Excess Cash </b></i><i><b>Account</b></i>”), as determined by proper completion of the CWCAM Asset Management CMBS Excess Cash Reconciliation (“<i><b>Excess Cash Worksheet</b></i>”) as shown on Exhibit 1.  The Manager shall deliver the Excess Cash Worksheet to the Owner by the fifteenth (15) day of each calendar month until the Cash Close Out Process is completed. The Manager shall disburse excess cash into the CWCAM REO Excess Cash Account pursuant to the wire instructions provided by CWCAM and included herein as Exhibit D.  The Manager hereby covenants and agrees that such wire instructions may only be changed upon receipt by the Manager of written notice from the Chief Financial Officer - Chief Accounting Officer of CWCAM. If the Excess Cash Worksheet shows excess cash balance of zero or less, no amount will be distributed to Owner; however, the Excess Cash Worksheet must be provided evidencing that there is no excess cash.  If at the time any Bank Account balance is less than the sum of the Minimum Balance plus the total amount of all outstanding current obligations of the Property, no amount will be distributed to Owner.  Notwithstanding that Manager is authorized to and shall make the disbursements set forth above to the extent funds are available, Owner will be solely liable for (i) all Operating Costs, Fixed Charges and (ii) all sales taxes, excise taxes, or other taxes which may be assessed by any taxing authority with respect to the Property or the operation thereof.</p>\n<p class=\"body\"><b>7.03</b>\t<b>Cash Close Out Process.</b></p>\n<p class=\"body\">     Within three (3) days after a sale of the Property, the Manager must notify Owner, in writing, of any outstanding action items relating to the Property (i.e. tax appeals, utility refunds, accounts payable, final Management Fee (including the Close-Out Fee), any final payroll, etc.) and the estimated amount of funds required to complete the Cash Close Out Process.  Within sixty (60) days, or such longer period of time as approved by Owner’s Representative, after the termination or expiration of this Agreement, the Manager shall forward to CWCAM the following items (the “<i><b>Cash Close Out Process</b></i>”): </p>\n<p class=\"body\">Final monthly report</p>\n<p class=\"body\">Final Excess Cash Worksheet</p>\n<p class=\"body\">All  cash remaining in the bank account</p>\n<p class=\"body\">Evidence of bank account closure, i.e., letter from the bank confirming closure of the account and a final bank statement with a zero balance.</p>\n<p class=\"body\"><b>7.0</b><b>4</b> \t<b>Disposition P</b><b>rocess.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 7</h2>", subtitleHtml: "<h3 class=\"art-sub\">DISBURSEMENTS (cont'd)</h3>", body: "<p class=\"body\">     In connection with a sale of the Property, the Manager shall perform the following as requested by Owner (collectively, the “<i><b>Disposition</b></i><i><b> Process</b></i>”): (1) supervise and coordinate inspections of the Property by the purchaser and its inspectors, appraisers, surveyors, engineers and other parties;  (2) respond to requests for rent rolls, balance of security deposit account, balance of monthly rental account, Operating Costs and other Property specific information, which information must be reviewed and approved by Owner before being delivered to the purchaser of the Property; (3) generate and provide Property prorations at least three (3) days prior to the closing of the sale of the Property and the final prorations on the closing date; and (4) perform such other actions and activities as may be reasonably requested by Owner. </p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 8</h2>", subtitleHtml: "<h3 class=\"art-sub\">INSURANCE</h3>", body: "<p class=\"body\"><b>8.01</b><b>\tInsurance Coverage.</b></p>\n<p class=\"body\">Owner shall procure and maintain such commercial general liability insurance and property insurance coverages as Owner deems necessary in its sole and absolute discretion.  Manager shall procure and maintain such commercial general liability insurance and other insurance coverages as set forth in said Exhibit A, unless otherwise instructed by Owner.  In connection with all significant construction at the Property, Owner or Manager (whichever is the contracting party) will cause the general contractor to maintain, with a reputable insurer, Builder’s Risk and General Liability insurance as set forth in Exhibit A.</p>\n<p class=\"body\"><b>8.02</b><b>\tInsurance Policies.</b></p>\n<p class=\"ind\">(a)\tAll insurance provided for under this Article 8 by Manager shall be effected by policies issued by Qualified Insurers of good reputation and of sound financial responsibility and shall be subject to Manager’s and Owner’s approval.  If permitted under the REMIC Requirements, such insurance may be carried under blanket policies covering the Property and other locations provided such policies otherwise comply with all of the requirements of Exhibit A.</p>\n<p class=\"ind\">(b)\tCertificates of Insurance shall be delivered to Owner and Manager on or before the Commencement Date.  All insurance policies shall be renewed, and proof of such renewals shall be delivered to Owner and Manager at least ten (10) days prior to their respective expiration dates.</p>\n<p class=\"ind\">(c)\tAll insurance policies procured by Manager under Section 8.01 shall be written in the name of Manager with Owner, and any other appropriate parties designated by Owner or Manager being named thereon as additional insureds (as their respective interests may appear), except for workers’ compensation insurance and other insurance with respect to which it is impractical and inappropriate to name other parties as additional insureds.</p>\n<p class=\"ind\">(d)\tEach party shall use all reasonable efforts to cause any property policy which it is responsible to obtain under Exhibit A to provide that the insurer shall not have any rights of subrogation to any claim which either party hereto may have or acquire against the other.  Neither Owner nor Manager shall have any claim against the other with respect to the failure of any insurance carrier to provide the coverage or protection placed with such carrier as contemplated by this Agreement. Nothing herein shall impact the Manager’s indemnity obligations in Article 9.</p>\n<p class=\"ind\">(e)\tCertificates of Insurance (and copies of policies, to the extent required) shall be sent to Manager and to Owner at their respective addresses set forth in Article 12 hereof and to the Mortgagee(s) at such addressees as the Mortgagee(s) shall designate.</p>\n<p class=\"ind\">(f)\tAll coverage limits and deductible amounts set forth in Exhibit A shall be reviewed by Owner and Manager from time to time for the purpose of determining the coverage limits and deductible amounts then appropriate for properties similar in type and construction to the Property and for the nature of the business being conducted.  Manager and Owner shall cooperate in good faith to arrive at an agreement on such matters; provided, however, that such coverages shall in any event comply with REMIC Requirements.</p>\n<p class=\"body\"><b>8.03</b><b>\tManager</b><b>’</b><b>s</b><b> Blanket Insurance Coverage.</b></p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 8</h2>", subtitleHtml: "<h3 class=\"art-sub\">INSURANCE (cont'd)</h3>", body: "<p class=\"body\">Manager may, at its option (but shall not be obligated to) make available to Owner the opportunity to participate in blanket insurance policies carried by Manager for other properties, including, without limitation other Manager’s properties and which cover all or any portion of the insurance coverage specified in Exhibit A (including all or any portion of that insurance required to be procured and maintained by Owner or lessor under Section 8.01).  If permitted under REMIC Requirements, Owner may (but shall not be required to) participate in such blanket policies if (a) Manager determines to make such coverage available to Owner, and (b) the premiums for, and the coverage and financial strength provided by the insurer(s) under such blanket policies applicable to the Property shall be competitive with the premiums for, and the coverage and financial strength provided by the insurer(s) from which Owner would otherwise obtain such insurance.  In such event, notwithstanding the provisions of Section 8.01 and Exhibit A hereof, Manager shall be responsible for procuring and maintaining, as an Operating Cost, all insurance coverage represented by such blanket policies and Owner shall be named as named insured on such blanket policies.</p>\n<p class=\"body\"><b>8.4</b><b>\tTenants’ Insurance Requirements.</b></p>\n<p class=\"body\">Manager shall ensure that all tenants at the Property present evidence of renters insurance not later than lease execution.  Insurance must remain in effect for the duration of the tenant’s lease term (and any extension thereof) and shall be in the form of a personal liability insurance policy covering resident and resident’s guests, for personal injury and property damage caused to third parties (including damage to Owner’s property by resident or resident’s guests), in a minimum policy coverage amount of $100,000.00 per occurrence.  Manager shall obtain and maintain written proof of such personal liability policy in the form of a declaration page or certificate of insurance prior to the date on which such tenant occupies a unit at the Property.  For the purpose of this provision tenants’ insurance shall be provided by an insurer qualified to write liability insurance policies in the state in which the Property is located.  Manager shall not sell, solicit or negotiate such insurance unless the Manager or their representative holds a valid license from the regulator in that state and for the line of authority being provided.   For the avoidance of doubt, Owner will receive no fee, commission, expense offset or other consideration due to requiring Manager to administer this multifamily tenants’ insurance requirement.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 9</h2>", subtitleHtml: "<h3 class=\"art-sub\">INDEMNIFICATION</h3>", body: "<p class=\"body\"><b>9.01</b><b>\tLiabilities; Indemnification; Third Parties.</b></p>\n<p class=\"ind\">(a)\tSubject to the terms of this Agreement, all debts and liabilities arising in the course of business of the Property or otherwise in connection with the use, occupancy or operation thereof (including, without limitation, all such liabilities under or with respect to environmental laws, hazards or claims) during the Term are and shall be the obligation of Owner, and Manager shall not be liable or otherwise responsible for any such debts or liabilities by reason of its management, supervision and operation of the Property during such Term, including, without limitation, work-related injury claims which may have been incurred, but have not been received by Manager or, if applicable, Owner as of the termination thereof, except for any debt, claims (whether in tort, contract or otherwise) or liability that arises because of Manager’s negligence, intentional misconduct, fraud, breach of this Agreement or actions beyond the scope of authority granted to Manager under this Agreement.  </p>\n<p class=\"ind\">(b)\tNotwithstanding anything to the contrary, Owner shall not be liable or responsible for any accident, claim (whether in tort, contract or otherwise), loss, injury or damage attributable to the negligence or willful misconduct of Manager, its partners, agents, employees, successors and assigns, or other Affiliates occurring or accruing on the Property during the term of the performance of this Agreement or in connection therewith, and Manager shall and does hereby fully indemnify, protect, defend and hold harmless Owner, all its venture partners, employees, agents, predecessors, successors and assigns or legal representatives (including without limitation Special Servicer and Sole Member) and other Affiliates from and against all liens, demands, suits, losses, costs, liabilities, claims (whether administrative or judicial, and whether in tort, contract or otherwise) and expenses or any combination thereof, including without limitation attorney’s fees and expenses, of any nature, kind or description, of any person or entity whomsoever, arising out of, caused by or resulting from (a) any act or omission constituting negligence or willful misconduct or breach of fiduciary duty by any officer, director, agent or employee of Manager in connection with Manager’s performance under this Agreement or (b) any action taken by or on behalf of Manager relating to the Property or to Owner which is not permitted by or pursuant to the provisions of this Agreement (collectively, “<i><b>Losses</b></i>”).  This indemnity shall not be limited in any way by any limitations on the amount or type of proceeds, damages, compensation acts, disability benefit acts or other employee benefit acts currently held by Owner or Manager.  The provisions of this Section shall survive the expiration or termination of this Agreement.</p>\n<p class=\"body\">Except as to specific acts or omissions for which Manager has agreed to indemnify Owner and its Affiliates and Special Servicer in paragraph (b) above, Owner hereby agrees to defend, indemnify and hold Manager and its Affiliates, and their respective agents, officers, employees, partners, members, directors and shareholders, harmless from and against Losses occurring out of or by reason of this Agreement or otherwise arising in connection with the ownership, use, occupancy or operation of the Property.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 9</h2>", subtitleHtml: "<h3 class=\"art-sub\">INDEMNIFICATION (cont'd)</h3>", body: "<p class=\"ind\">(c)\tNo person or entity shall be deemed to be a third party beneficiary of any term or provision of this Agreement, including, without limitation, the terms and provisions of this Section 9.01, and no person or entity shall have any rights of subrogation or similar rights under this Section 9.01, other than Affiliates of Owner and Manager, respectively, entitled to indemnification pursuant to the provisions of this Article 9.  Notwithstanding the foregoing, Special Servicer shall be deemed a third party beneficiary of the provisions of this Agreement.  All indemnification obligations under this Agreement and the provisions of this Article 9 shall survive the expiration and any termination of this Agreement.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 10</h2>", subtitleHtml: "<h3 class=\"art-sub\">CASUALTY AND CONDEMNATION</h3>", body: "<p class=\"body\"><b>10.01</b><b>\tCasualty.</b></p>\n<p class=\"ind\">(a)\tIf, during the Term, the Property incurs minor damage by fire, casualty or other cause, Owner shall, unless otherwise determined by Owner, in its sole and absolute discretion, and subject to REMIC Requirements, at its sole cost and expense and with all reasonable diligence, repair or replace the damaged portion of the Property to the reasonably same condition as existed previously.  To the extent available, proceeds from the insurance described in Article 8 shall be applied to such repairs or replacements.</p>\n<p class=\"ind\">(b)\tIn the event damage or destruction to the Property from any cause materially and adversely affects the operation of the Property, Owner, at Owner’s sole and absolute option, shall promptly commence and complete repairing, rebuilding or replacement of the Property to substantially the same character as existed prior to the damage or destruction provided replacement is justified in comparison to the anticipated profitability of the Property during the remaining Term, and provided that the available insurance proceeds (plus the amount of the deductible with respect thereto) permit such repair, rebuilding or replacement.  In the event Owner chooses to not undertake the repairs, rebuilding or replacements specified above, Manager’s sole remedy shall be to terminate this Agreement upon sixty (60) days’ advance written notice to the Owner without the payment of any early termination fee or other penalty of any kind, except for the Close-Out Fee to the extent Manager is required to perform the Disposition Process.</p>\n<p class=\"ind\">(c)\tUpon approval of the Owner, Manager shall have the right to discontinue operating any portion of the Property to the extent Manager deems necessary to comply with applicable law, ordinance, regulation or order or as necessary for the safe and orderly operation of the Property. </p>\n<p class=\"body\"><b>10.02</b><b>\tCondemnation.</b></p>\n<p class=\"ind\">(a)\tIn the event all or substantially all of the Property shall be taken in any eminent domain, condemnation, compulsory acquisition, or similar proceeding by any competent authority for any public or quasi-public use or purpose, or in the event a portion of the Property shall be so taken, but the result is that it is uneconomic to continue to operate the Property as a Property of the same character and class, this Agreement shall terminate.  Owner shall have the right to initiate such proceedings, as it deems advisable to recover any condemnation award to which it may be entitled.</p>\n<p class=\"ind\">(b)\tIn the event a portion of the Property shall be taken by the events described in Section 10.02(a) or the entire Property is affected but on a temporary basis, and the result is not to make it unreasonable to continue to operate the Property, this Agreement shall not terminate.  However, provided that Owner determines that the cost of repair, rebuilding or replacement is justified in comparison to the anticipated profitability of the Property during the remaining term of this Agreement, and if permitted under REMIC Requirements so much of any award for any such partial taking or condemnation as shall be necessary to render the Property equivalent to its condition prior to such event shall be used for such purpose; the balance of such award, if any, shall be paid to Owner.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 11</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFAULT AND TERMINATION</h3>", body: "<p class=\"body\"><b>11.01</b><b>\tEvents of Default.</b></p>\n<p class=\"body\">It shall be an event of default hereunder (an “<i><b>Event of Default</b></i>”) if any one or more of the following events shall occur:</p>\n<p class=\"ind\">(a)\tSubject to the terms of Article 16 below, if either party shall fail to timely perform any of its duties and obligations under, shall otherwise breach the terms of this Agreement or shall commit any fraud or intentional misappropriation of funds.</p>\n<p class=\"ind\">(b)\tIf either party shall do any of the following:</p>\n<p class=\"ind\">(i)\tvoluntarily or involuntarily be dissolved (except that if either party is a partnership and is dissolved solely by reason of the death, insanity, disappearance, bankruptcy or lack of legal capacity of one or more of its general partners and its remaining partners, within sixty (60) days, elect, pursuant the partnership agreement of such partnership to continue such partnership’s business, then such party shall not be considered as “dissolved” for the purposes hereof);</p>\n<p class=\"ind\">(ii)\tapply for or consent to the appointment of a receiver, trustee or liquidator of all or a substantial part of its assets;</p>\n<p class=\"ind\">(iii)\tfile a voluntary petition in bankruptcy or otherwise voluntarily avail itself of any federal or state laws for the relief of debtors;</p>\n<p class=\"ind\">(iv)\tadmit in writing its inability to pay its debts as they become due;</p>\n<p class=\"ind\">(v)\tmake a general assignment for the benefit of creditors;</p>\n<p class=\"ind\">(vi)\tfile a petition or an answer seeking reorganization or arrangement with creditors or to take advantage of any insolvency law or file an answer admitting the material allegations of any petition filed against it in any bankruptcy, reorganization or insolvency proceeding;</p>\n<p class=\"ind\">(vii)\tbe the subject of an order, judgment or decree entered by any court of competent jurisdiction, in the application of any one or more creditors of such party adjudicating it a bankrupt or insolvent or approving a petition seeking reorganization or appointing a receiver, trustee or liquidator of all or a substantial part of its assets, and such order, judgment or decree shall become final; or</p>\n<p class=\"ind\">(viii)\ttake any action which is a violation of a REMIC Requirement or which, in Owner’s sole determination, is likely to result in a violation of any REMIC Requirement.</p>\n<p class=\"body\"><b>11.02</b><b>\tTermination.</b></p>\n<p class=\"ind\">(a)\tUpon the occurrence of any Event of Default under Section 11.01(a) by or with respect to one of the parties hereto (the “<i><b>Defaulting Party</b></i>”), the other party hereto (the “<i><b>Non-Defaulting Party</b></i>”) shall have the right (exercisable by the giving of written notice to the Defaulting Party) to terminate this Agreement if the Defaulting Party fails to remedy such Event of Default within ten (10) days after its receipt of notice to remedy if such default relates to the payment of a sum of money and, in all other cases, within thirty (30) days after its receipt of notice to remedy; provided, however, that if such Event of Default be of a non-monetary nature and if it cannot reasonably be remedied within said thirty (30) day period, then such thirty (30) day period shall be deemed to be extended for such additional period as may reasonably be required to remedy the same if the Defaulting Party shall promptly commence to remedy upon receipt of notice from the Non-Defaulting Party and shall continue therewith with due diligence.  Notwithstanding anything to the contrary contained herein, there shall not be any cure period afforded to Manager for any Event of Default occurring as a result of fraud or intentional misappropriation of funds by Manager.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 11</h2>", subtitleHtml: "<h3 class=\"art-sub\">DEFAULT AND TERMINATION (cont'd)</h3>", body: "<p class=\"ind\">(b)\tWith respect to the occurrence of an Event of Default under Section 11.01(b), this Agreement shall terminate upon such occurrence.</p>\n<p class=\"ind\">(c)\tThe terms of this Agreement shall not be deemed to impair the right of any party to exercise any right or remedy, whether for damages, injunctions, specific performance or otherwise, upon any breach or wrongful termination hereof, available at law or in equity.</p>\n<p class=\"body\"><b>11.03</b><b>\tPost-Termination Matters: Reimbursements to Manager.</b></p>\n<p class=\"body\">Upon any termination or expiration of this Agreement for any reason whatsoever (including, without limitation, pursuant to Section 11.02 above), Owner expressly agrees that Manager may subject to Manager’s compliance with the Cash Close Out Process, if applicable, remove any of its documents which are proprietary to Manager (including, without limitation, employee files, manuals, software programs, stored data, and internal correspondence of a proprietary nature) but specifically excluding financial records, documents, correspondence or other materials proprietary to the Property which shall be deemed property of Owner.  Manager shall have the right to make copies of all other non-proprietary files and information relating to its management of the Property.   Upon such termination or expiration for any reason other than Manager’s default, within twenty (20) days of billing thereof, Owner shall pay to Manager, in addition to any other amounts due pursuant to this Agreement (i) the Close-Out Fee, if applicable, (ii) Manager’s reasonable out-of-pocket costs incurred by reason of requests by Owner for assistance after termination of this Agreement and not otherwise reasonably expected of Manager in the orderly termination of its operations at the Property and (iii) any unpaid fees and other charges and reimbursements due Manager hereunder, including, without limitation, the Reimbursed Expenses. </p>\n<p class=\"body\"><b>11.04</b><b>\tPost-Termination Matters: WARN Act.</b></p>\n<p class=\"body\">In the event of any termination hereunder, Owner shall use reasonable efforts to cause the entity which shall succeed Manager as the operator of the Property to hire a sufficient number of the employees at the Property to avoid the occurrence, in connection with the termination of a “closing” under the WARN Act.  This Section 11.04 shall survive the expiration or termination of this Agreement.</p>\n<p class=\"body\"><b>11.05</b><b>\tExtension of Date of Termination.</b></p>\n<p class=\"body\">Notwithstanding anything to the contrary contained in this Agreement, the date of termination of this Agreement because of Manager’s default hereunder, shall be extended so that the date of termination after notice of termination is given to or by Manager shall be on a date which is not earlier than fifteen (15) days plus the number of days, if any, Manager is required to give its employees advance notice of termination of employment as required by the WARN Act, or any similar federal or state statute.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 12</h2>", subtitleHtml: "<h3 class=\"art-sub\">NOTICES</h3>", body: "<p class=\"body\">All consents, approvals, notices or other communications provided for in this Agreement shall be in writing and delivered in person, or sent by reputable and trackable overnight delivery service or by postage prepaid Registered or Certified Mail, to the respective addresses for Owner and Manager set forth below (with a copy thereof transmitted to the party to which such notice is being given by email to the applicable address set forth below), until such time as written notice, as provided hereby, of a change of address with a new address (and/or email address) to be used thereafter is delivered to the other party. Notices will be deemed delivered upon confirmation of delivery at the current notice address referenced above. Upon request, a party shall send copies of any notice or communication by ordinary mail as instructed by the other party.</p>\n<p class=\"body\">All notices and other communications required or permitted to be given hereunder shall be given to the applicable party at the address set forth below:</p>\n<p class=\"body\"><b>If to Owner, to:</b></p>\n<p class=\"ind\">%%OWNER_NOTICE_NAME%%<br/>%%OWNER_NOTICE_ADDR1%%<br/>%%OWNER_NOTICE_ADDR2%%<br/>Attention: %%OWNER_NOTICE_ATTN%%<br/>Telephone Number: %%OWNER_NOTICE_PHONE%%<br/>Email: %%OWNER_NOTICE_EMAIL%%</p>\n<p class=\"body\"><b>If to Manager, to:</b></p>\n<p class=\"ind\">%%MGR_NOTICE_NAME%%<br/>%%MGR_NOTICE_ADDR1%%<br/>%%MGR_NOTICE_ADDR2%%<br/>Attention: %%MGR_NOTICE_ATTN%%<br/>Telephone Number: %%MGR_NOTICE_PHONE%%<br/>Email: %%MGR_NOTICE_EMAIL%%</p>\n<p class=\"ind\">In order to facilitate communications between Owner and Manager, Owner designates the Owner&#39;s Representative to act for Owner pursuant to this Agreement, and Manager designates Manager&#39;s Representative to act for Manager pursuant to this Agreement.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 13</h2>", subtitleHtml: "<h3 class=\"art-sub\">RELATIONSHIP AND FURTHER ACTIONS</h3>", body: "<p class=\"body\"><b>13.01</b><b>\tRelationship.</b></p>\n<p class=\"body\">Manager and Owner shall not be construed as joint venturers or partners of each other and neither shall have the power to bind or obligate the other except as set forth in this Agreement.</p>\n<p class=\"body\"><b>13.02</b><b>\tFurther Actions.</b></p>\n<p class=\"body\">Owner agrees to execute all contracts, agreements and documents, and to take all actions as may be reasonably necessary to comply with the provisions of this Agreement and the intent hereof.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 14</h2>", subtitleHtml: "<h3 class=\"art-sub\">APPLICABLE LAW; SEVERABILITY</h3>", body: "<p class=\"body\">The interpretation, validity and performance of this Agreement shall be governed by the laws of the State in which the Property is located (without regard to its conflicts of laws provision). If any of the terms and provisions hereof shall be held invalid or unenforceable for any reason, such invalidity or unenforceability shall in no event affect any of the other terms or provisions hereof, all such other terms and provisions to be valid and enforceable to the fullest extent permitted by law.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 15</h2>", subtitleHtml: "<h3 class=\"art-sub\">SUCCESSORS AND ASSIGNS</h3>", body: "<p class=\"body\"><b>15.01</b><b>\tAssignment.</b></p>\n<p class=\"ind\">(a)\tManager, with the consent of Owner, shall have the right to assign from time to time this Agreement and its rights and interests hereunder to any successor or assignee of Manager which may result from any merger, consolidation or reorganization with, or any sale or assignment to, any corporation, individual, partnership or other entity which shall acquire all or substantially all of Manager’s property management business.  Any such assignee shall agree to be bound by the terms and conditions of this Agreement.  Except as hereinabove provided, Manager shall not assign or in any manner sell or transfer any of its rights and interests as Manager hereunder without the prior written consent of Owner, which consent may be withheld in Owner’s sole discretion.  Except as permitted above, any assignment by Manager to any third party without Owner’s prior written consent shall be void <i>ab initio </i>and an Event of Default by Manager.</p>\n<p class=\"ind\">(b)\tOwner shall have the right (but not the obligation) to assign this Agreement to any third party acquiring the Property subject to Manager’s prior written consent, which consent will not be unreasonably withheld or delayed.  Any such assignee shall assume all obligations of Owner under this Agreement and the transferring Owner shall be released of all liability hereunder.  </p>\n<p class=\"body\"><b>15.02</b><b>\t</b><b>Binding Effect.</b></p>\n<p class=\"body\">Subject to the restrictions on assignment set forth elsewhere in this Agreement, this Agreement shall be binding upon and inure to the benefit of Owner and its successors and assigns, and shall be binding upon and inure to the benefit of Manager and its successors and assigns.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 16</h2>", subtitleHtml: "<h3 class=\"art-sub\">FORCE MAJEURE</h3>", body: "<p class=\"body\"><b>16.01</b><b>\tOperation of Property.</b></p>\n<p class=\"body\">If at any time during the term hereof it becomes necessary in Manager’s reasonable opinion to cease operation of the Property in order to protect the Property and/or the health, safety and welfare of the tenants and/or their respective employees of the Property for reasons including, without limitation, acts of war, terrorism, insurrection, civil strife and commotion, labor unrest or acts of God (a “<i><b>Force Majeure</b></i>”), then in such event Manager may (upon notice to Owner) close and cease operation of all or part of the Property, reopening and commencing operation when Manager, in consultation with Owner, deems that such may be done without jeopardy to the Property, its tenants and their respective employees.  Notwithstanding anything to the contrary contained in Article 11 or otherwise in this Agreement, any such cessation of operation (a “<i><b>Force Majeure Cessation</b></i>”) occurring pursuant to this Section 16.01 shall not be deemed or considered an Event of Default.  Manager shall immediately reopen the Property after the termination or end of the Force Majeure event, which caused the Property to be shut down. </p>\n<p class=\"body\"><b>16.02</b><b>\tExtension of Time.</b></p>\n<p class=\"body\">With respect to any obligation to be performed by a party during the Term, such party shall in no event be liable for failure to perform when prevented by any Force Majeure cause beyond the reasonable control of such party such as strike, lockout, breakdown, accident, order or regulation of or by any governmental authority, failure of supply or inability, by the exercise of reasonable diligence, to obtain supplies, parts or employees necessary to perform such obligation, or war or other emergency.  The time within which such obligation shall be performed shall be extended for a period of time equivalent to the delay from such cause, and Manager shall have peaceable and quiet possession of the Property and shall be entitled to operate the Property, free from eviction or disturbance during any such period of time.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 17</h2>", subtitleHtml: "<h3 class=\"art-sub\">GENERAL PROVISIONS</h3>", body: "<p class=\"body\"><b>17.01</b><b>\t</b><b>Authorization.</b></p>\n<p class=\"body\">Owner represents that it has full power and authority to execute this Agreement and to be bound by and perform the terms hereof.  Manager represents that it has full power and authority to execute this Agreement and to be bound by and perform the terms hereof.  On request, each party shall furnish to the other party evidence of such authority.</p>\n<p class=\"body\"><b>17.02</b><b>\tFormalities.</b></p>\n<p class=\"body\">Any change to or modification of this Agreement must be in writing signed by both parties hereto.  This Agreement shall be executed in one or more counterparts, each of which shall be deemed an original.  The captions for each Article and Section are intended for convenience only.</p>\n<p class=\"body\"><b>17.03</b><b>\t</b><b>Consents.</b></p>\n<p class=\"ind\">Except as otherwise expressly provided in this Agreement, wherever in this Agreement it is provided that an act or proposed act of Owner or Manager is subject to the consent or approval of the other, such consent or approval shall not be unreasonably withheld or delayed; provided, however, that Owner’s withholding of consent or disapproval shall be deemed reasonable if based upon Owner’s determination that the giving of Owner’s consent or approval would or could result in the violation of any REMIC Requirements.  If the approval or consent of one party hereto is required for any act or matter contemplated by the other party, the party desiring such consent may give to the party whose consent is desired, notice specifying in reasonable detail, the matter to which consent is requested.  Unless otherwise specified herein, if the party whose consent is requested does not, within twenty (20) business days after actual receipt of such notice, respond positively or negatively to such notice in writing, the requested consent shall be deemed withheld.</p>\n<p class=\"body\"><b>17.04</b><b>\tEstoppel Certificate.</b></p>\n<p class=\"body\">Either party shall, at any time and from time to time, upon not less than ten (10) days’ prior written request from the other, execute, acknowledge and deliver to the requesting party, in form reasonably satisfactory to the requesting party, a written statement certifying (if true); (i) that this Agreement is unmodified and in full force and effect (or if there have been modifications, that the same is in full force and effect as modified and stating the modifications); (ii) that there is no outstanding notice of an Event of Default hereunder and, to the best of such party’s knowledge, no event has occurred or condition exists which, with the giving of notice or the passage of time or both, would constitute an Event of Default hereunder, and (iii) such other accurate information as may be reasonably requested by the requesting party or by any of the Interested Persons (as hereinafter defined).  It is intended that any such statement delivered pursuant to this Section 17.04 may be relied upon by the requesting party, any current or prospective Mortgagee or other party providing financing to Owner or Manager (as the case may be), a prospective purchaser of the Property or permitted assignee of Manager’s rights and interests hereunder, and the respective successors and assigns of any of the foregoing (the “<i><b>Interested Persons</b></i>”).</p>\n<p class=\"body\"><b>17.05</b><b>\tNo Representations.</b></p>\n<p class=\"ind\">(a)\tOwner and Manager acknowledge there have been no representations, inducements, promises or agreements made by Manager or Owner other than those specifically set forth herein.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 17</h2>", subtitleHtml: "<h3 class=\"art-sub\">GENERAL PROVISIONS (cont'd)</h3>", body: "<p class=\"ind\">(b)\tFinancial projections, budgets or similar forecasts as may have been prepared or in the future will be prepared by Manager or its Affiliates may not take into account, nor make provisions for, any rise or decline in local or general economic conditions or other factors beyond the control of Manager.  Manager and its Affiliates cannot and do not warrant or guarantee in any way said financial projections, budgets or other forecasts.  Any financial projections, budgets or forecasts provided have been prepared on the basis of information available at the time of such preparation and Manager’s and its Affiliate’s experience in the property industry.  Said financial projections, budgets and forecasts have been prepared for information only and not as an inducement for action.  Owner understands and acknowledges that no guaranty is made or implied by Manager or its Affiliates as to the cost, or the future financial success or profitability, of the Property.</p>\n<p class=\"body\"><b>17.06</b><b>\tNot an Interest in Real Estate.</b></p>\n<p class=\"body\">This Agreement is not, and shall not be deemed or construed, at any time or for any purpose, to be or create any interest in real estate or any lien or other encumbrance of any kind whatsoever against the Property or the land upon which it is erected and neither this Agreement nor any memorandum hereof shall be recorded.</p>\n<p class=\"body\"><b>17.07</b><b>\tSpecial Stipulations.</b>  The Special Stipulations set forth in Exhibit B attached hereto are incorporated herein by this reference.  In the event of any conflict between any of the terms, conditions and provisions set forth in the Special Stipulations and any of the terms, conditions and provisions set forth elsewhere in this Agreement, the terms, conditions and provisions of the Special Stipulations shall control.</p>\n<p class=\"body\"><b>17.08</b>\t<b>Time.</b>  Time is of the essence of this Agreement.</p>\n<p class=\"body\"><b>17.09</b>\t<b>Severability.</b>  If any provision of this Agreement or application to any party or circumstances shall be determined by any court of competent jurisdiction to be invalid or unenforceable to any extent, the remainder of this Agreement or the application of such provision to such person or circumstances, other than those as to which it is so determined invalid or unenforceable, shall not be affected thereby, and each provision hereof shall be valid and shall be enforced to the fullest extent permitted by law.</p>\n<p class=\"body\"><b>17.10</b><b>\tAuthority Limited.</b>  Manager’s authority shall be derived wholly from this Agreement, and Manager has no authority to act for or represent Owner except as herein expressly specified.</p>\n<p class=\"body\"><b>17.11</b>\t<b>Exclusiveness of Compensation.</b>  The payments to be made to Manager hereunder shall be in lieu of all other and further compensation or commissions of any nature whatsoever for the services described herein and this Agreement shall be considered as a special agreement between the parties hereto covering the appointment and compensation of Manager to the exclusion of any other method of compensation unless otherwise agreed to in writing.  Without limiting the foregoing and except for the compensation expressly set forth in this Agreement, Manager shall not be entitled to any commission, fee or other compensation upon the sale or other disposition of the Property by Owner.</p>" },
  { titleHtml: "<h2 class=\"art\">ARTICLE 17</h2>", subtitleHtml: "<h3 class=\"art-sub\">GENERAL PROVISIONS (cont'd)</h3>", body: "<p class=\"body\"><b>17.12</b><b>\tCounterparts. </b>This Agreement may be executed in multiple counterparts, each of which when so executed and delivered shall be deemed to be originals and together shall constitute one and the same instrument.  The parties hereto consent and agree that this Agreement may be signed and/or transmitted by facsimile, e-mail of a .pdf document or using electronic signature technology (e.g., via DocuSign or similar electronic signature technology), and that such signed electronic record shall be valid and as effective to bind the parties so signing as a paper copy bearing such parties’ handwritten signatures. The parties further consent and agree that (1) to the extent a party signs this Agreement using electronic signature technology, by clicking “SIGN”, such party is signing this Agreement electronically, and (2) the electronic signatures appearing on this Agreement shall be treated, for purposes of validity, enforceability and admissibility, the same as handwritten signatures.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT A</h2>", subtitleHtml: "", body: "<p class=\"body\">Manager shall procure the insurance coverages hereinafter set forth and ensure that they are in full force and effect on the Commencement Date and that they remain in full force and effect throughout the Term of this Agreement at Manager’s sole cost and expense. Each of Managers policies of insurance as appropriate will contain a provision affording the Owner and Owners agents additional insured status, loss payee status or other extension arising from vicarious liability due to Property Manager’s negligence:</p>\n<table class=\"fee ins-table\"><tr><th>Coverage</th><th>Amount of Insurance</th></tr><tr><td>Workers’ Compensation</td><td class=\"fee-amt\">Statutory</td></tr><tr><td>Employer’s Liability</td><td class=\"fee-amt\">$1,000,000</td></tr><tr><td>Fidelity (Employee Dishonesty)</td><td class=\"fee-amt\">As required</td></tr><tr><td>Money and Securities</td><td class=\"fee-amt\">As required</td></tr><tr><td>Commercial General Liability</td><td class=\"fee-amt\">$1,000,000 per occurrence/$2,000,000 aggregate annual per location</td></tr><tr><td>Cyber Liability:</td><td class=\"fee-amt\">$1,000,000 or as required by Owner</td></tr><tr><td>Employment Practices Liability:</td><td class=\"fee-amt\">$1,000,000.00 or as required by Owner</td></tr><tr><td>Umbrella/Excess Liability:</td><td class=\"fee-amt\">  $5,000,000 (per location aggregate):</td></tr><tr><td class=\"ins-sub\">Including -</td><td></td></tr><tr><td>Products/Completed Operations</td><td class=\"fee-amt\">   $1,000,000</td></tr><tr><td class=\"ins-sub\">Contractual Liability</td><td></td></tr><tr><td>Personal Injury</td><td class=\"fee-amt\">$1,000,000</td></tr><tr><td>Environmental Liability (if required by Owner):</td><td class=\"fee-amt\">$1,000.000 (including Legionella, lead paint, mold)</td></tr><tr><td>Automobile Liability</td><td class=\"fee-amt\">$1,000,000:</td></tr><tr><td class=\"ins-sub\">Owned Vehicles</td><td></td></tr><tr><td class=\"ins-sub\">Non-Owned Vehicles</td><td></td></tr><tr><td class=\"ins-sub\">Uninsured motorist where required by statute</td><td></td></tr><tr><td class=\"ins-sub\">Automobile Physical Damage (Optional):</td><td></td></tr><tr><td>Comprehensive</td><td class=\"fee-amt\">   (To value if insured)</td></tr><tr><td class=\"ins-sub\">Collision</td><td></td></tr><tr><td class=\"ins-sub\">Professional Liability (Seniors Properties Only) with terms approved by Owner:</td><td></td></tr><tr><td class=\"ins-sub\">$1,000,000 per occurrence / $2,000,000 general aggregate.</td><td></td></tr><tr><td class=\"ins-sub\">If the policy covers multiple locations, location aggregates and higher limits will be required by Owner.</td><td></td></tr><tr><td class=\"ins-sub\">Excess Professional Liability minimum $5,000,000 (or greater as required by Owner).</td><td></td></tr><tr><td class=\"ins-sub\">Policy terms must meet minimum Owner review.</td><td></td></tr><tr><td class=\"ins-sub\">If coverage is provided on a claims made basis an extended reporting period for all policies not earlier than 36 months or equivalent coverage to be agreed by Owner.</td><td></td></tr><tr><td class=\"ins-sub\">All insurance coverages provided for under this Exhibit A shall comply with the requirements of Section 8.02.</td><td></td></tr></table>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations</h3>", body: "<p class=\"ind\">A.\tIndependent Contractor.  Owner and Manager intend, acknowledge and agree that the relationship between Owner and Manager pursuant to this Agreement is that of a principal and an independent contractor and that all employees and personnel necessary for the operation of the Property shall in every instance be the employees or independent contractors of Manager and not of Owner or Special Servicer.  At the expense of Manager, which shall be a Centralized Service Expense, executive personnel of Manager will oversee the performance of Manager’s obligations under this Agreement and the general supervision, direction and control of Manager’s employees and personnel in accordance with normal and prudent practices in the property management industry.  Manager shall exercise due care in hiring employees and selecting persons and entities to provide labor, services, products and materials required for Manager to perform its obligations under this Agreement.  Nothing contained herein shall be deemed to constitute Owner and Manager as partners or joint venturers.  Manager hereby covenants that it will refrain from any activity that could create, or be deemed to create, a conflict of interest with Owner in the discharge of Manager’s obligations under this Agreement.</p>\n<p class=\"ind\">B.\tGeneral Operations.  Manager shall operate the Property and all its facilities in a manner in accordance with the highest standards achievable consistent with the Preliminary Operating Budget and the applicable Approved Budget in a good, orderly, safe, clean, sanitary, and sightly condition, and so as to maximize the earnings of the Property and its underlying value and to provide such services at the Property as are normally provided by operators of properties of comparable class and size, subject, however to the Preliminary Operating Budget or the applicable Approved Budget.</p>\n<p class=\"ind\">C.\tNotices of Claim of Injury or Damage.  Manager shall notify the Owner (and any insurer of Owner or the Property) of any personal injury or property damage occurring to or claimed by any employee, contractor, guest, customer, lessee or other third party on or with respect to the Property promptly upon obtaining knowledge thereof and shall promptly forward to the Owner within two (2) business days after Manager’s receipt thereof, any summons, subpoena, or legal document served upon the Manager relating to actual or alleged potential liability of the Owner, the Manager or the Property.</p>\n<p class=\"ind\">D.\tAssistance with Proposed , Financing, Refinancing.  Manager shall cooperate with and assist Owner from time to time in any attempt(s) by Owner to sell, finance or refinance the Property.  Such cooperation shall not entitle Manager to any additional compensation and Manager shall not be deemed to be acting as a broker unless Owner and Manager enter into a separate written agreement engaging Manager as broker with respect to the Property.  Such cooperation shall include, without limitation, answering prospective purchasers’ or lenders’ questions about the Property or its operations.  </p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">E.\tHazardous Materials, Toxic Wastes and Asbestos.  If during the term of this Agreement, Manager becomes aware of the existence of hazardous materials or wastes, toxic substances or wastes, asbestos or asbestos-bearing materials and the like (collectively, “<i><b>Hazardous </b></i><i><b>Materials</b></i>”) at, in, on, or under the Property, Manager shall immediately notify Owner of the condition, both orally and in writing.  Subject to Section 5.06, Owner shall exclusively determine such further course of action with respect to such hazardous condition.  Manager shall not supervise or oversee any work involving remediation of any hazardous or potentially hazardous wastes or conditions unless specifically hired by Owner to do so pursuant to a separate agreement between Owner and Manager.  Manager shall always use its good faith commercially reasonable efforts to prevent and detect the occurrence or existence of any hazardous condition at the Property and shall reasonably cooperate with Owner, at no additional fee or cost to Owner, in abating and remedying any hazardous condition at the Property and in operating the Property so as to eliminate any such hazardous condition.  Notwithstanding anything contained herein to the contrary, including, without limitation, the provisions of Section 5.06 hereof to the contrary, Owner and Manager agree that Owner shall have exclusive control over any issue concerning hazardous or potentially hazardous conditions at the Property and that Manager shall have no authority to act for or on behalf of Owner or to make any decisions or elections on behalf of Owner with respect to any such conditions.</p>\n<p class=\"ind\">F.\tOwner Representative.  For the purposes of this Agreement, Special Servicer in its capacity as Owner’s authorized agent is acting as Owner’s representative; the burdens and liabilities of this Agreement shall extend only to Owner, and Special Servicer shall have no liability hereunder.</p>\n<p class=\"ind\">G.\tCentralized Services Expenses.  Other than the items as otherwise may be expressly approved in writing by Owner, nothing contained herein shall be deemed to permit Manager to charge, as an Operating Cost or as a Reimbursed Expense or otherwise, any costs or expenses of Manager’s executive personnel or for Manager’s overhead, office, administrative, or non-reimbursable expenses as set forth in Section 6.05 of the Agreement (the “<i><b>Centralized Services Expenses</b></i>”), it being the intent of Owner and Manager that the Management Fee payable by Owner shall include all such items.</p>\n<p class=\"ind\">H.\tGeneral Compliance with Laws.  Manager shall operate and maintain the Property in compliance with all applicable laws, statutes, ordinances, rules, regulations, requirements, orders, notices, and determinations of any federal, state or municipal authority, and the requirements of any insurance companies covering any of the risks against which the Property is insured.  Without limiting the generality of the immediately foregoing sentence, Manager shall: (i) upon request of Owner, contract with a qualified independent contractor to prepare an inspection report on behalf of Owner to determine whether the Property is in compliance with the Americans with Disabilities Act and if not in compliance, shall propose to Owner a plan to bring the non-complying Property into compliance; and (ii) promptly notify Owner of the necessity for and assist Owner in obtaining and maintaining any and all licenses, permits, or approvals required of Owner by any applicable federal, state or municipal authority in connection with the ownership or operation of the Property.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">I.\tEqual Opportunity Employer.  Manager represents and warrants to Owner that Manager is an equal opportunity non-discriminatory employer.  Manager and Owner each mutually agree that there shall be no discrimination against or segregation of any person or of a group of persons on account of race, color, creed, religion, handicap, sex, sexual orientation or national origin, in the lease, transfer, use, occupancy, advertising, promotion, sale, tenure or enjoyment of the Property or in the provision of services thereto, nor shall Owner or Manager permit any such practice or practices of discrimination or segregation with reference to the selection, location, number, use or occupancy of tenants.</p>\n<p class=\"ind\">J.\tFidelity Bond.  Manager shall maintain, pay for and keep in full force fidelity bond and professional liability, a/k/a errors and omissions insurance coverage on all of its employees, agents, officers and directors who are involved in, or employed in connection with, the performance of Manager’s obligations under this Agreement, which coverage shall be in a dollar amount equal to the greater of: (i) $1,000,000.00; or (ii) three (3) times the monthly average Total Revenues projected in the Preliminary Operating Budget or the applicable Approved Budget, unless otherwise specified by Owner in writing, plus a tail/discovery period of at least two (2) years.  Evidence of such fidelity bond and professional liability, a/k/a errors and omissions insurance coverage will be provided to Owner at Owner’s request.  The cost of such bond and professional liability, a/k/a errors and omissions insurance coverage shall be the expense of the Manager. </p>\n<p class=\"ind\">K.\tDuties Upon Termination of Agreement.  The termination of this Agreement for any reason shall not affect any right, obligation or liability which has accrued under this Agreement on or before the effective date of such termination.  Upon termination of this Agreement for any reason, the authority of Manager under this Agreement shall immediately cease and Manager shall have no further right to act for Owner or withdraw funds from the Bank Account, except as allowed by Owner in connection with the Cash Close Out Process.  In addition, upon the occurrence of an Event of Default by Manager, Owner shall have no further duty to pay or deposit any funds into the Bank Account or to pay to or for the benefit of Manager any funds other than the Management Fee.  In the event of termination, Manager shall fulfill all reporting and accounting functions hereunder through the period for which Owner agrees to pay Manager a Close-Out Fee.  Upon termination Manager shall also: (i) deliver to Owner possession of the Property; (ii) deliver to Owner as received any monies due Owner under this Agreement but received after such termination; (iii) deliver to Owner all materials and supplies, keys, copies of contracts and documents, and copies of all other accounting papers and records pertaining to the operation of the Property as the Owner shall request; (iv) assign any right Manager may have in and to any existing contracts relating to the operation and maintenance of the Property as the Owner shall require and for which Owner agrees in writing to assume Manager’s duties and obligations arising thereunder after the date of assignment; and (v) deliver to Owner or Owner’s duly appointed agent all records, contracts, leases, receipts for deposits and unpaid bills in existence at the time of termination and all other papers or documents which pertain to the Property.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">L.\tDisclosure.  Manager shall disclose to Owner for Owner’s reasonable approval any controlling ownership interest of Manager, any officer or employee of Manager, or any immediate family member (parent or parent-in-law, spouse, child, brother, sister, brother-in-law or sister-in-law or stepparent) of any officer or employee of Manager in any corporation, partnership, joint venture or other business which provides materials, products or services, directly or indirectly, for the Property.  Such disclosure shall be made to Owner, in writing, at least ten (10) days prior to the proposed entering into any contract or agreement with such business for the provision of such products, materials or service.  Any contract or agreement made by Manager with a related party shall be at rates or amounts not greater than those which would have been paid under an arms-length contract with a non-related party.</p>\n<p class=\"ind\">M.\tWarranties and Representations of Manager.  Manager hereby makes the following representations, warranties and covenants to Owner, all of which shall survive the execution and delivery of this Agreement:</p>\n<p class=\"ind\">(i)\tManager was duly organized, is validly existing, is in good standing under the laws of the state of its formation or incorporation, is in good standing under the laws of the state in which the Property is located, and has complied with all applicable laws in order to conduct business in such state;</p>\n<p class=\"ind\">(ii)\tManager has sufficient expertise, staff and other resources to carry out Manager’s duties hereunder in a prompt, efficient, and diligent manner;</p>\n<p class=\"ind\">(iii)\tThis Agreement constitutes a legal, valid, and binding agreement of Manager, enforceable against Manager in accordance with its terms, except as limited by bankruptcy, insolvency, receivership and similar laws of general application to creditors’ rights from time to time in effect;</p>\n<p class=\"ind\">(iv)\tManager has or will obtain all licenses and permits, including all governmental licenses and permits, necessary to legally and validly execute, deliver and perform this Agreement;</p>\n<p class=\"ind\">(v)\tNeither Manager nor any entity Affiliate of Manager is in any way affiliated with any party to the PSA and is an “independent contractor” during the term of this Agreement and any extension thereof, as defined in Treas. Reg. Section 1.856-(6), with respect to the PSA;</p>\n<p class=\"ind\">(vi)\tThe terms and conditions of this Agreement are reasonable and customary for the area and type of property which is the subject of this Agreement; and</p>\n<p class=\"ind\">(vii)\tThe Management Fees required to be paid to Manager under this Agreement are consistent with general market standards and are no less favorable than the management fees required to be paid to managers of similar properties for services similar to those described in the Agreement.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">N.\tConfidentiality.  As used herein, the term “<i><b>Confidential Information</b></i>” means any information which is acquired by Manager in carrying out its duties under this Agreement and which had not become part of the body of public information prior to its disclosure in violation of this Special Stipulation N, including information regarding the Property or any litigation pertaining thereto.  Except as otherwise required by any law or court order, or as authorized or permitted by Owner, Manager shall not disclose or permit the disclosure of any Confidential Information to anyone other than Owner, Owner’s counsel, Special Servicer, or to persons designated by Owner’s counsel, except as reasonably required to carry out the duties of Manager under this Agreement.  Manager shall execute and deliver to Owner any document requested by Owner evidencing or otherwise concerning Manager’s agreement to comply with the terms of this Special Stipulation N or any other agreement binding on Owner with respect to Confidential Information.  Manager shall immediately notify Owner and its authorized agent of any court order or subpoena requiring disclosure of Confidential Information, shall cooperate with Owner’s counsel in the appeal or challenge of any such order or subpoena, and shall not disclose any Confidential Information pursuant to such court order or subpoena until Owner has exhausted any lawful and timely appeal or challenge that owner elects to file or make.  Owner shall be responsible for retaining counsel if Owner decides to appeal or challenge Manager for Manager’s reasonable fees and expenses related to the appeal or challenge of any such order or subpoena.  All original documents shall be retained by Owner.</p>\n<p class=\"body\">Owner may give Manager copies of documents in connection with the Property.  Upon termination of this Agreement, all information in the possession of Manager relating to the Property shall be returned to Owner; provided, however, that Manager may retain copies of any information which Manager reasonably considers necessary for Manager’s confidential business records.  Manager shall take reasonable measures to avoid any unintentional or inadvertent disclosure of any Confidential Information to any unauthorized person by its employees, agents, or attorneys.  Manager shall not use any Confidential Information for Manager’s own gain, except as specifically permitted by this Agreement.  The provisions of this Special Stipulation N shall not preclude Manager from disclosing Confidential Information relating to the Property to third parties as reasonably required to carry out the duties of Manager under this Agreement, so long as Manager obtains from any such persons or entities the execution and delivery of an agreement that imposes the same obligations upon such parties with respect to Confidential Information as were imposed upon Manager under this Special Stipulation N.  The provisions of this Special Stipulation N shall survive the expiration and termination of this Agreement.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">O.\tBusiness Conduct.  The maintenance of extremely high standards of honesty, integrity, impartiality, and conduct by Manager and its employees and agents is essential to assure the proper performance of business and the maintenance of public confidence in the Owner.  The Owner expects Manager to uphold and meet these high standards and to use its best judgment to avoid misconduct and conflicts of interest and to require the same of its employees and agents.  In general, Manager shall avoid any action which might result in or create the appearance of using its position for private gain, giving preferential treatment to any person, losing complete independence or impartiality, or making Owner’s decisions outside authorized channels.  Manager shall not take any action that would adversely affect the confidence of the public in the integrity of the Owner and shall not engage in conduct prejudicial to the Owner, including criminal, dishonest or immoral conduct.  Manager shall not (i) misuse Owner’s property; (ii) use inside information obtained as a result of retention by Owner for private gain for Manager or another person, particularly one with whom it has family, business or financial ties; (iii) use its retention by Owner to coerce, or give the appearance of coercing, a person to provide financial benefit to the employee or another person, particularly one with whom he or she has family, business or financial ties; or (iv) because of such retention, receive or solicit from a person having business with Owner anything of more than <i>de minim</i><i>i</i><i>s</i> value as a gift, gratuity, loan, entertainment, or favor for the Manager or another person.  Manager shall disclose all other employment and those financial interests Manager has which may be relevant to its contractual relationship with Owner.  Other employment or financial interests that are held to conflict with Owner interests will not be permitted.  Any violation of this Special Stipulation O by Manager or its employees, agents or representatives will constitute a breach of this Agreement by Manager.  The provisions of this Special Stipulation O shall survive the expiration and termination of this Agreement.</p>\n<p class=\"ind\">P.\tLimitation on Liability.  Manager agrees to look solely to Owner to the extent of Owner’s interest in the Property for the satisfaction of any liability or obligation arising under this Agreement or the transactions contemplated hereby, or for the performance of any of the covenants, warranties, obligations or other agreements contained herein, and further agrees not to sue or otherwise seek to enforce any personal obligation against any of Owner’s affiliates with respect to any matters arising out of or in connection with this Agreement or the duties and obligations contemplated hereby.</p>\n<p class=\"ind\">Q.\tReports relating to Servicing and Pooling Agreement.  At Owner’s request, Manager shall cooperate in providing any information or completing any reports required to meet any reporting requirements that are necessary to comply with the PSA or which is otherwise necessary to preserve the Property as “foreclosure property” within the meaning of Code Section 860G(a)(8), to ensure that the Owner will continue to qualify as a REMIC within the meaning of Code Section 860D(a) or to ensure that the Owner will not become subject to any tax including, but not limited to, the tax on “prohibited transactions” as defined in Code Section 860F(a)(2)(B), or the tax on “net income from foreclosure property” as defined in Code Section 860G(c)(2).</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT B</h2>", subtitleHtml: "<h3 class=\"art-sub\">Special Stipulations (cont'd)</h3>", body: "<p class=\"ind\">R.\tREMIC Requirements.  The parties hereto understand and acknowledge that Sole Member is a REMIC and that Sole Member and Owner are subject to requirements and limitations relating to their interests in the Property in order to preserve Sole Member’s status as a REMIC under the PSA (the “<i><b>REMIC Requirements</b></i>”).  The REMIC Requirements shall specifically include, without limitation, the following:</p>\n<p class=\"ind\">(i)\tManager, in the exercise of its good faith and reasonable judgment and in accordance with applicable law, shall manage, conserve, protect and operate the Property in the same manner in which, and with the same care, skill and diligence, as is normal and usual in its general property management and operation activities on behalf of third parties or on behalf of itself, whichever is higher, with respect to properties which are comparable to the Property and with a view to the maximization of Net Operating Income and the value of the Property.</p>\n<p class=\"ind\">(ii)\tManager shall manage, conserve and protect the Property in a manner which does not cause the Property to fail to qualify as “foreclosure property” within the meaning of Section 860G(a)(8) of the Code (determined without regard to the exception applicable for purposes of Section 860D(a) of the Code).</p>\n<p class=\"ind\">(iii)\tManager will ensure that Owner will not be deemed to provide any non-customary services to guests, invitees, tenants or customers of the Property and will not receive any income from such non-customary services within the meaning of Treas. Reg. Section 1.856-4(b).</p>\n<p class=\"ind\">(iv)\tSubject only to the availability of sufficient funds in the Bank Account, Manager shall pay all costs and expenses incurred in connection with the operation and management of the Property pursuant to the Agreement, including, without limitation (A) all insurance premiums due and payable in respect of the Property; (B) all real estate taxes and assessments in respect of the Property that may result in the imposition of a lien thereon; and (C) all costs and expenses reasonable and necessary to protect, maintain, manage, operate, repair and restore the Property, and Manager shall remit all Net Operating Income as detailed on the Excess Cash Worksheet to Owner as soon as practicable, but in no event later than thirty (30) days following the receipt thereof by Manager.</p>\n<p class=\"ind\">(v)\tManager shall make no Capital Expenditures unless provided for in the Preliminary Operating Budget or in the applicable Operating Budget without the prior written consent of Owner, which consent may be withheld.</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT C</h2>", subtitleHtml: "<h3 class=\"art-sub\">Legal Description of the Property</h3>", body: "<p class=\"body\">*[See Attached]</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT D</h2>", subtitleHtml: "<h3 class=\"art-sub\">Wire Instructions</h3>", body: "<p class=\"body\">Property Manager to send wire instructions to: %%WIRE_INSTRUCTIONS_TO%%</p>" },
  { titleHtml: "<h2 class=\"art\">APPENDIX</h2>", subtitleHtml: "<h3 class=\"art-sub\">Monthly Reporting Requirements</h3>", body: "<p class=\"body\">Manager shall submit Monthly Financial Reporting Packages to ______________designee no later than fifteen (15) calendar days after the end of each month.  Each package shall include:  </p>\n<p class=\"body\"><i>Narrative Summary </i>(Should provide a brief summary of monthly activity issues/concerns related to the property from an operational and marketing standpoint.) </p>\n<p class=\"body\"><i>Balance sheet</i></p>\n<p class=\"body\"><i>Monthly, year-to-date and trailing-12 operating statements according </i></p>\n<p class=\"body\"><i>Monthly Variance Report</i> (This report must clearly explain any line item in which the variance from actual to budget exceeds 10% or $500 of budget.)</p>\n<p class=\"body\"><i>Rent Roll </i>(must include deposits, rental rate, lease term,  charges, options and concessions)</p>\n<p class=\"body\"><i>Aging Statement</i>  </p>\n<p class=\"body\"><i>Bank Statements and Reconciliations</i></p>\n<p class=\"body\"><i>General Ledger</i></p>\n<p class=\"body\"><i>Month-to-Date Trial Balance</i></p>\n<p class=\"body\"><i>Check Register </i></p>\n<p class=\"body\"><i>Property Management Fee Calculation</i></p>\n<p class=\"body\"><i>Market Update</i> (Must include survey of competitive properties. Survey must provide number of units or square feet, rental rates, concessions and occupancy. The update should also include any changes in the neighborhood that may affect the property.)</p>\n<p class=\"body\"><i>Move-in / Move-Out Schedule</i> </p>\n<p class=\"body\"><i>Inspection report</i>, including, without limitation, for the pool</p>\n<p class=\"body\"><i>Excess Cash </i><i>Worksheet</i> (Exhibit 1)</p>\n<p class=\"body\">Final Accounting (upon termination or expiration of this Agreement)</p>\n<p class=\"body\">Any other documents as required by Owner</p>" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT 1</h2>", subtitleHtml: "<h3 class=\"art-sub\">Excess Cash Worksheet</h3>", body: "" },
  { titleHtml: "<h2 class=\"art\">EXHIBIT 2</h2>", subtitleHtml: "<h3 class=\"art-sub\">Capital Improvement Approval Form</h3>", body: "" },
];
